L1_1.m_fTitleTalkTime = 0.06
L1_1.m_SubTitle_KOREA = "공군 기술 연구소 임시 선착장\n델타 세븐 기함, 엔터프라이즈 <color=#ffd34c>개장 작업 중</color>\nCSE Lv. <b>0</b>"
L1_1.m_fSubTitleTalkTime = 0.06
L1_1.m_BGFileName = "BLACK"
L1_1.m_StartBGMFileName = "CUTSCENE_AMBIENT_WIND"
L1_1.m_SubTitle_JPN = "空軍技術研究所の臨時船着き場\nデルタセブンの旗艦、エンタープライズの<color=#ffd34c>改装作業中</color>\nCSE Lv. <b>0</b>"
L1_1.m_SubTitle_ENG = [[
Air Force Research Lab Temporary Dock,
Delta Seven Flagship, Enterprise <color=#ffd34c>undergoing remodeling</color>
CSE Lv. <b>0</b>]]
L1_1.m_SubTitle_TWN = "空軍技術研究所臨時機庫\n第七三角洲部隊艦船 企業號 <color=#ffd34c>改裝作業中</color>\nCSE Lv. <b>0</b>"
L1_1.m_SubTitle_THA = "ลานจอดชั่วคราวห้องวิจัยกองทัพอากาศ\nเอ็นเตอร์ไพรส์ ยานรบหลักของเดลต้าเซเว่น<color=#ffd34c>อยู่ระหว่างการดัดแปลง</color>\nCSE เลเวล <b>0</b>"
L1_1.m_SubTitle_VTN = "Căn Cứ Tạm Thời Phòng Nghiên Cứu Lực Lượng Không Quân, \nTàu Đô Đốc Delta Seven, Enterprise <color=#ffd34c>đang được tu sửa</color>\nCấp CSE<b> 0 </b>"
L1_1.m_SubTitle_SCN = "空军研究所临时船坞\n德尔塔部队旗舰，企业号<color=#ffd34c>改装工作进行中</color>\nCSE Lv. <b>0</b>"
L1_1.m_SubTitle_DEU = "Temporäres Dock des Technischen Forschungsinstituts der Luftwaffe\nDelta Seven Flaggschiff, Enterprise, <color=#ffd34c>wird umgestaltet</color>\nCSE-St.: <b>0</b>"
L1_1.m_SubTitle_FRA = "Laboratoire de recherche de l'Armée de l'Air, Passerelle temporaire\nVaisseau amiral du Delta Seven Enterprise <color=#ffd34c>Rénovation en cours</color>\nNiveau d'ECM : <b>0</b>"
