L4_1 = {}
L4_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 351
L4_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_BGCrash = 10
L4_1.m_fBGCrashTime = 1
L4_1.m_StartBGMFileName = "CUTSCENE_TALK_01"
L4_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L4_1.m_Talk_KOREA = "매버릭, 그쪽 일은 어때?"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "マーベリック、そっちはどう？"
L4_1.m_Talk_ENG = "How are things going Maverick?"
L4_1.m_Talk_TWN = "麥伯利，你那邊如何？"
L4_1.m_Talk_THA = "สถานการณ์เป็นไงบ้างมาเวอริก?"
L4_1.m_Talk_VTN = "Mọi việc thế nào rồi, Maverick?"
L4_1.m_Talk_SCN = "麦博利，你的工作怎么样？"
L4_1.m_Talk_DEU = "Wie läuft es Maverick?"
L4_1.m_Talk_FRA = "Comment ça se passe de ton côté, Maverick ?"
L5_1 = {}
L5_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 351
L5_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L5_1.m_Talk_KOREA = "말도 마. 엔진 갈아치우면 에이허브에 탑재된 기상 조절 시스템도 뜯어 놓으란다."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "最悪。エンジンを替えた後にはエイハブに搭載されてる天候調節システムも外しておけって。"
L5_1.m_Talk_ENG = "Don’t get me started. They said that once we’re done replacing the engine, we have to dismantle the weather control system attached to the Ahab."
L5_1.m_Talk_TWN = "別說了，換掉引擎的話，原本搭載在亞哈上的氣象調節系統也要拆掉。"
L5_1.m_Talk_THA = "อย่าให้ต้องเริ่มบ่น พวกนั้นบอกว่าพอเราเปลี่ยนเครื่องยนต์เสร็จแล้ว ก็ต้องแยกชิ้นส่วนระบบควบคุมสภาพอากาศที่ติดอยู่กับอาฮับ"
L5_1.m_Talk_VTN = "Tôi chẳng muốn nói đâu. Họ nói rằng một khi chúng ta thay thế xong động cơ, chúng ta sẽ phải tháo dỡ hệ thống kiểm soát thời tiết gắn liền với Ahab."
L5_1.m_Talk_SCN = "别提啦。如果更换发动机，安装在亚哈上的天气控制系统也得拆除。"
L5_1.m_Talk_DEU = "Frag bloß nicht! Sie haben gesagt, dass wir, sobald wir mit dem Austausch des Motors fertig sind, das an der Ahab angebrachte Wetterkontrollsystem demontieren müssen."
L5_1.m_Talk_FRA = "M'en parle pas. Une fois fini de remplacer le moteur, je dois démanteler le système de surveillance météorologique attaché à l'Ahab."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 351
L6_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L6_1.m_Talk_KOREA = "그것도 열─두─ 시간 안에."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "それも十～二～時間内に。"
L6_1.m_Talk_ENG = "And they want this done in TWELVE. HOURS."
L6_1.m_Talk_TWN = "而且還必須在12個小時內完成！"
L6_1.m_Talk_THA = "และพวกนั้นอยากให้เสร็จในสิบสองชั่วโมง"
L6_1.m_Talk_VTN = "Và họ muốn điều này phải được hoàn hành trong MƯỜI. HAI. GIỜ."
L6_1.m_Talk_SCN = "而且还得在十二小时之内！"
L6_1.m_Talk_DEU = "Und sie wollen, dass das innerhalb von ZWÖLF STUNDEN erledigt wird."
L6_1.m_Talk_FRA = "Le tout, en DOUZE HEURES."
L7_1 = {}
L7_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 351
L7_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L7_1.m_Talk_KOREA = "역시 군인 놈들은 제정신이 아니야. 오늘 안에 방 정리 다 하라는 우리 엄마보다 더 심해."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "やっぱ軍人の奴らは正気じゃない。今日中に部屋の掃除を終わらせろっていうお母さんよりひどいんだ。"
L7_1.m_Talk_ENG = "I knew it, these military guys are nuts. They’re worse than my mom when she tells me to clean my room within today."
L7_1.m_Talk_TWN = "軍人果然腦袋都不太正常，我媽頂多叫我今天之內把房間整理好，他們比我媽還超過！"
L7_1.m_Talk_THA = "กะแล้วเชียวว่าพวกกองทัพนี่มันบ้าจริงๆ แย่กว่าแม่ฉันตอนที่บอกให้ทำความสะอาดห้องภายในวันนี้อีก"
L7_1.m_Talk_VTN = "Tôi biết điều đó, những gã quân nhân này quá điên đi. Họ còn tệ hại hơn mẹ tôi khi mẹ bảo tôi phải dọn phòng trong ngày hôm nay."
L7_1.m_Talk_SCN = "果然那些军人们不是很清醒。这比妈妈让我今天之内收拾好房间还要糟糕。"
L7_1.m_Talk_DEU = "Ich wusste es, diese Soldaten sind verrückt. Sie sind schlimmer als meine Mutter, wenn sie mir sagt, dass ich mein Zimmer innerhalb eines Tages aufräumen soll."
L7_1.m_Talk_FRA = "Je le savais, ces militaires sont fous. Ils sont pires que ma mère qui me rabat sans cesse de nettoyer ma chambre."
L8_1 = {}
L8_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 351
L8_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L8_1.m_Talk_KOREA = "에잇! 이럴 줄 알았으면 차라리 편안한 수용소 안에 있는 건데!"
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "えいっ！　こうなるとわかってたら、いっそ楽な収容所に残っていればよかった！"
L8_1.m_Talk_ENG = "Damn it! If I knew it would be like this, I would’ve just stayed comfortably in prison!"
L8_1.m_Talk_TWN = "嘖！早知如此，還不如乾脆就待在收容所裡！"
L8_1.m_Talk_THA = "เวรตะไลเอ๊ย! ถ้ารู้ว่าจะเป็นงี้นะ ฉันคงอยู่เฉยๆ ในคุกให้สบายไปแล้ว!"
L8_1.m_Talk_VTN = "Chết tiệt! Nếu tôi biết nó sẽ như thế này, tôi thà cứ thoải mái trong tù!"
L8_1.m_Talk_SCN = "嘿！如果早知道会发生这种情况，我宁愿待在舒适的收容所里！"
L8_1.m_Talk_DEU = "Verdammt! Wenn ich gewusst hätte, dass es so sein würde, wäre ich einfach im Gefängnis geblieben!"
L8_1.m_Talk_FRA = "Fait chier ! Si j'avais su que ça se passerait comme ça, je serais resté dans ma cellule !"
L9_1 = {}
L9_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 351
L9_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L9_1.m_Talk_KOREA = "거기선 몸이라도 편했다고! 밥도 맛있었고!"
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "あそこは少なくとも体は楽だったんだよ！　ご飯も美味しかったし！"
L9_1.m_Talk_ENG = "At least it was comfortable there! And the food was good!"
L9_1.m_Talk_TWN = "在所裡多舒適！連飯都比較好吃！"
L9_1.m_Talk_THA = "อย่างน้อยในนั้นก็สบาย! แถมของกินอร่อยอีกต่างหาก!"
L9_1.m_Talk_VTN = "Ít nhất thì ở đó cũng thoải mái! Và thức ăn cũng ất ngon!"
L9_1.m_Talk_SCN = "至少在那里我不会很累！而且饭也很好吃！"
L9_1.m_Talk_DEU = "Zumindest war es dort bequem! Und das Essen war auch gut!"
L9_1.m_Talk_FRA = "Au moins, c'était confortable là-bas ! Et la bouffe était bonne !"
L10_1 = {}
L10_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 351
L10_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_BGCrash = 20
L10_1.m_fBGCrashTime = 0.5
L10_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L10_1.m_Talk_KOREA = "군대 밥이 수용소 보다 더 맛없다니 이게 말이 돼?!"
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "軍隊のご飯が収容所よりまずいなんてあり得ないでしょう！？"
L10_1.m_Talk_ENG = "How can military food be more disgusting than prison food?!"
L10_1.m_Talk_TWN = "軍隊的伙食竟然比收容所的還差！這說得過去嗎？！"
L10_1.m_Talk_THA = "อาหารในกองทัพมันอี๋กว่าในคุกได้ไงวะ?"
L10_1.m_Talk_VTN = "Sao mà đồ ăn quân đội lại tệ hơn đồ ăn trong tù được?!"
L10_1.m_Talk_SCN = "军队的伙食竟然比收容所还差，这像话吗？！"
L10_1.m_Talk_DEU = "Wie kann denn nur der Militärfraß ekelhafter sein als der Gefängnisfraß?!"
L10_1.m_Talk_FRA = "Comment les rations militaires peuvent-elle avoir un goût encore plus infect que ce qu'on nous donne en prison ?!"
L11_1 = {}
L11_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 351
L11_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L11_1.m_Talk_KOREA = "욕망에 굴복해선 안돼, 친구!"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "欲望に負けるな、友よ！"
L11_1.m_Talk_ENG = "You must not give in to your urges, comrade!"
L11_1.m_Talk_TWN = "朋友，不能屈服於口腹之慾！"
L11_1.m_Talk_THA = "แกต้องไม่ยอมพ่ายแพ้ต่อสิ่งยั่วยุสิวะสหาย!"
L11_1.m_Talk_VTN = "Đừng có để phần \"con\" lên ngôi chứ, đồng chí!"
L11_1.m_Talk_SCN = "不要屈服于欲望，我的朋友！"
L11_1.m_Talk_DEU = "Du darfst deinem Drang nicht nachgeben, Kamerad!"
L11_1.m_Talk_FRA = "Ne cède pas à la gourmandise, camarade !"
L12_1 = {}
L12_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 351
L12_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L12_1.m_Talk_KOREA = "우린 어둠 속에서 자유를 위해 투쟁하는 하나이자 일곱! 일곱이자 하나!"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "私たちは闇の中で自由のために戦う一人で七人！　七人で一人！"
L12_1.m_Talk_ENG = "We fight for freedom within the darkness! Seven for one! One for seven!"
L12_1.m_Talk_TWN = "我們可是在黑暗中為自由而奮鬥的一群人，我們是七！是七也是一！"
L12_1.m_Talk_THA = "เราต่อสู้ท่ามกลางความมืดมิดเพื่อพิชิตอิสรภาพนะเว้ย! เจ็ดเพื่อหนึ่ง! หนึ่งเพื่อเจ็ด!"
L12_1.m_Talk_VTN = "Chúng ta chiến đấu cho sự tự do trong bóng tối! Bảy người vì một người! Một người vì bảy người!"
L12_1.m_Talk_SCN = "我们可是在黑暗中为自由而战的黑客团队！"
L12_1.m_Talk_DEU = "Wir kämpfen für die Freiheit in der Dunkelheit! Sieben für einen! Einer für sieben!"
L12_1.m_Talk_FRA = "Nous sommes les soldats de la liberté, la lueur dans les ténèbres ! Sept pour un ! Un pour sept !"
L13_1 = {}
L13_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 351
L13_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_StartFXSoundName = "FX_CUTSCEN_TADA2"
L13_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L13_1.m_Talk_KOREA = "다-크 세븐이라고."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "ダーークセブンなんだよ。"
L13_1.m_Talk_ENG = "We are Daark Seven."
L13_1.m_Talk_TWN = "我們是Dark 7！"
L13_1.m_Talk_THA = "เราคือดาร์กเซเว่นไง"
L13_1.m_Talk_VTN = "Chúng ta là Dark Seven."
L13_1.m_Talk_SCN = "黑暗九人帮——Dark Seven！"
L13_1.m_Talk_DEU = "Wir sind Daark Seven."
L13_1.m_Talk_FRA = "Daark Seven !"
L14_1 = {}
L14_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 351
L14_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L14_1.m_Talk_KOREA = "분명 넘버 1이 우릴 구하러 올 거야!"
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "きっとナンバー1が私たちを助けに来てくれる！"
L14_1.m_Talk_ENG = "Surely Number 1 will come save us!"
L14_1.m_Talk_TWN = "1號一定會來救我們的！"
L14_1.m_Talk_THA = "หมายเลข 1 ต้องมาช่วยเราแน่นอน!"
L14_1.m_Talk_VTN = "Chắc chắn Số 1 sẽ đến cứu chúng ta!"
L14_1.m_Talk_SCN = "1号一定会来救我们的！"
L14_1.m_Talk_DEU = "Ich bin sicher, Nummer 1 wird kommen, um uns zu retten!"
L14_1.m_Talk_FRA = "Numéro 1 viendra sûrement nous sauver !"
L15_1 = {}
L15_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 351
L15_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L15_1.m_Talk_KOREA = "그, 그래, 넘버 1이라면 분명 우리가 이대로 고통 받게 내버려 둘 리 없어!"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "そ、そう、ナンバー1ならきっと私たちが苦しんでるところを見捨てないはずだ！"
L15_1.m_Talk_ENG = "Th-that's right! Knowing Number 1, there’s no way that he’ll leave us suffering like this!"
L15_1.m_Talk_TWN = "嗯…你說的沒錯，1號不會讓我們就這樣一直受苦的！"
L15_1.m_Talk_THA = "จะ-จริงด้วย! ถ้าเป็นหมายเลข 1 ละก็ เขาต้องไม่ทิ้งเราให้ต้องทรมานแบบนี้แน่!"
L15_1.m_Talk_VTN = "Đ-đúng vậy! Đó là Số 1 mà, không đời nào cậu ấy lại để chúng ta phải chịu đựng thế này!"
L15_1.m_Talk_SCN = "没、没错。我相信1号不会坐视我们遭受这样的痛苦！"
L15_1.m_Talk_DEU = "Na klar! Nummer 1 wird uns definitiv nicht so leiden lassen!"
L15_1.m_Talk_FRA = "O-Oui, tu as raison ! Le connaissant, il ne nous laissera pas en difficulté comme ça pendant bien longtemps..."
L16_1 = {}
L16_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 351
L16_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L16_1.m_Talk_KOREA = "그리고…… 좀 미덥진 않지만 넘버2도 있고……."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "あと……ちょっと頼りないけどナンバー2もいるし……"
L16_1.m_Talk_ENG = "Also... Although not very trustworthy, there’s also Number 2..."
L16_1.m_Talk_TWN = "況且……還有不太靠譜2號……"
L16_1.m_Talk_THA = "แถม... ถึงจะไม่น่าเชื่อถือนัก แต่ก็ยังมีหมายเลข 2 ด้วยนะเว้ย..."
L16_1.m_Talk_VTN = "Ngoài ra... Dù không đáng tin lắm, nhưng còn có Số 2..."
L16_1.m_Talk_SCN = "而且……还有不算太可靠的2号……"
L16_1.m_Talk_DEU = "Und … er ist zwar ein bisschen unzuverlässig, aber es gibt auch noch Nummer 2 ..."
L16_1.m_Talk_FRA = "Et puis... elle n'est pas aussi fiable, mais il y a aussi Numéro 2..."
L17_1 = {}
L17_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 351
L17_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L17_1.m_Talk_KOREA = "저, 정말? 넘버2가 우릴 도와줄까?"
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "ほ、本当？　ナンバー2が私たちを助けてくれるかな？"
L17_1.m_Talk_ENG = "R-really? But will Number 2 help us?"
L17_1.m_Talk_TWN = "真…真的嗎？2號會幫我們嗎？"
L17_1.m_Talk_THA = "จะ-จริงเรอะ? แต่หมายเลข 2 จะช่วยเราเหรอวะ?"
L17_1.m_Talk_VTN = "T-thật sao? Nhưng liệu Số 2 có giúp chúng ta không?"
L17_1.m_Talk_SCN = "真、真的吗？你认为2号也会帮我们？"
L17_1.m_Talk_DEU = "W-wirklich? Nummer 2 wird uns helfen?"
L17_1.m_Talk_FRA = "V-Vraiment ? Numéro 2 va nous aider ?"
L18_1 = {}
