L19_1 = {}
L19_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 351
L19_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L19_1.m_Talk_KOREA = "솔직히 말하면…… 아니."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "正直に言うと……望み薄。"
L19_1.m_Talk_ENG = "To be honest... I don’t think so."
L19_1.m_Talk_TWN = "說實話嗎……不會。"
L19_1.m_Talk_THA = "เอาจริงๆ ก็... คงจะไม่ว่ะ"
L19_1.m_Talk_VTN = "Thành thật mà nói... tôi không nghĩ vậy."
L19_1.m_Talk_SCN = "老实说……不。"
L19_1.m_Talk_DEU = "Um ehrlich zu sein ... Ich glaube eher nicht."
L19_1.m_Talk_FRA = "Pour être honnête ... Je ne pense pas."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 351
L20_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L20_1.m_Talk_KOREA = "……크흥! 사실 내 생각도 그래."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "……チーン！　実は私もそう思う。"
L20_1.m_Talk_ENG = "...Ahem! Honestly, I also don’t think so either."
L20_1.m_Talk_TWN = "……咳咳！其實我也覺得不會。"
L20_1.m_Talk_THA = "...อะแฮ่ม! ฉันก็ว่างั้นเหมือนกันว่ะ"
L20_1.m_Talk_VTN = "... E hèm! Thành thật mà nói, tôi cũng không nghĩ vậy."
L20_1.m_Talk_SCN = "……唉！其实我也是这么认为的。"
L20_1.m_Talk_DEU = "... Hm! Ehrlich gesagt glaube ich es auch nicht."
L20_1.m_Talk_FRA = "... Ahem ! Ouais, moi non plus."
