L22_1 = {}
L22_1.m_CutScenKey_Talk = "EP9_ACT2_STAGE1_START@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 351
L22_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L22_1.m_Talk_KOREA = "우리 의견이 같은 건 좋은 일이지만 내 셔츠로 코 풀지 마!"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "同じ意見なのは嬉しいけど、私のシャツで鼻かまないでよ！"
L22_1.m_Talk_ENG = "It’s good that we see eye to eye, but don’t blow your nose on my shirt!"
L22_1.m_Talk_TWN = "我很高興我們有共識，但誰准你用我的襯衫擤鼻涕的！"
L22_1.m_Talk_THA = "ดีนะที่เราเห็นตรงกัน แต่อย่าสั่งขี้มูกใส่เสื้อฉันสิวะ!"
L22_1.m_Talk_VTN = "Thật tốt khi chúng ta có chung suy nghĩ, nhưng đừng xì mũi vào áo sơ mi của tôi chứ!"
L22_1.m_Talk_SCN = "虽然我们的意见能够统一是件好事。但不要拿我的衬衫擤鼻涕！"
L23_1 = "Schön, dass wir uns einig sind, aber putz dir nicht die Nase mit meinem Shirt!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "C'est cool de discuter comme ça, mais tu peux arrêter de te moucher dans ma chemise s'il te plaît ?"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP9_ACT2_STAGE1_START@23#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 23
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 351
L23_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L24_1 = "거기 프리라이더 콤비, 손수건 좀 갖다 줄래?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "そこのフリーライダーコンビ、ハンカチ持ってきてくれる？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "You there, the Free Riders duo, can you bring me a handkerchief?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "我說免費騎士雙人組，手帕借一下吧？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "คู่หูฟรีไรเดอร์ตรงนั้นน่ะ เอาผ้าเช็ดหน้ามาให้หน่อยได้มั้ย?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Này, bộ đôi Free Riders, có thể cho tôi một chiếc khăn tay không?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "那边的免费乘风者的搭档，能给我拿条手帕吗？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Hey, ihr da drüben! Das Free Rider Duo! Könnt ihr mir mal ein Taschentuch bringen?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Vous là bas, les deux Free Riders ! Vous voulez bien m'apporter un mouchoir ?"
L23_1.m_Talk_FRA = L24_1
