L27_1 = "m_Face"
L28_1 = "UNIT_HATE"
L26_1[L27_1] = L28_1
L27_1 = "FX_COMBAT_ALL_FOOT_STEP_LANDING_BIG"
L26_1.m_StartFXSoundName = L27_1
L27_1 = "AKI_FREEDOM_NULL_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "m_Pos"
L28_1 = "L"
L26_1[L27_1] = L28_1
L27_1 = "지금 함선 모듈 옮기는 거 안 보여요? 엄청 무겁다고요, 이거!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "今艦船のモジュール運んでる途中じゃないですか！　めっちゃ重いんですよ、これ！"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Can’t you see that we’re moving the ship module right now? It’s really heavy, you know!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "你沒看到我正在搬艦船模組嗎？這個很重欸！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ไม่เห็นเหรอว่าเราย้ายโมดูลยานรบกันอยู่น่ะ? มันหนักจะตายรู้มั้ย!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Không thể thấy là chúng tôi đang bận di chuyển mô-đun tàu sao? Nó thực sự rất nặng đấy!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "你没看到我们现在正在搬运舰船模块吗？这个很重的！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Siehst du nicht, dass wir das Schiffsmodul gerade bewegen? Es ist wirklich schwer!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Tu vois pas qu'on déplace les modules du vaisseau, là ? C'est vraiment lourd, ce truc !"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP9_ACT2_STAGE1_START@27#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 27
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 351
L27_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "m_Face"
L29_1 = "UNIT_DESPAIR"
L27_1[L28_1] = L29_1
L28_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "m_Pos"
L29_1 = "R"
L27_1[L28_1] = L29_1
L28_1 = "m_Crash"
L27_1[L28_1] = 10
L28_1 = "가, 가택 경비원에게 이런 중노동을 시키다니……. 너무해요……"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "か、家宅の警備員にこんな重労働をさせるなんて……ひどいです……"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I-I can’t believe they’re making a homebody like me do such heavy labor... This is cruel..."
L27_1.m_Talk_ENG = L28_1
L28_1 = "竟…竟然叫私人護衛做這種苦力……好過分……"
L27_1.m_Talk_TWN = L28_1
L28_1 = "มะ-ไม่อยากเชื่อเลยนะคะว่าจะให้เจ้าหน้าที่รักษา\nความปลอดภัยประจำบ้านมาใช้แรงงานหนักขนาดนี้... โหดร้ายชะมัด..."
L27_1.m_Talk_THA = L28_1
L28_1 = "T-tôi không thể tin nổi họ lại khiến đội bảo an làm những công việc nặng nhọc như vậy... Điều này thật tàn nhẫn..."
L27_1.m_Talk_VTN = L28_1
L28_1 = "竟、竟然让安防干这么辛苦的工作……太过分了……"
L27_1.m_Talk_SCN = L28_1
L28_1 = "I-ich kann nicht glauben, dass sie einen Stubenhocker wie mich so hart arbeiten lassen ... Das ist echt unverschämt ..."
L27_1.m_Talk_DEU = L28_1
L28_1 = "J'arrive pas à croire qu'ils nous utilisent pour faire ce travail... quels ingrats..."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
