L29_1 = {}
L30_1 = "EP9_ACT2_STAGE1_START@29#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 29
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 351
L29_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L30_1 = "미안한데 어쩌겠어. 우리 중에 부족한 중장비를 대신해 줄 사람은 카운터인 너희뿐인걸."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "悪いけど仕方ないでしょ。私たちの中で足りない重装備の代わりに働いてくれそうな人はカウンターの二人だけなんだから。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I’m sorry, but what else can we do? Out of the people here, the only ones who can act as alternatives for the heavy equipment that we don’t have are you Counters."
L29_1.m_Talk_ENG = L30_1
L30_1 = "不好意思，但我們也是有苦衷的。誰叫你們是制裁者，現在就只有制裁者能代替我們所缺乏的重型設備。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ขอโทษทีนะ แต่เราจะทำอะไรได้อีกล่ะ? ในบรรดาพวกที่อยู่ที่นี่ คนที่พอจะเป็นตัวเลือกสำหรับอุปกรณ์หนักได้ก็มีแต่เคาน์เตอร์อย่างพวกเธอนี่แหละ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi xin lỗi, nhưng chúng tôi còn có thể làm gì được nữa? Trong số những người ở đây, những người duy nhất có thể thay chúng tôi xử lý trang bị nặng như thế là chính các Counter mà."
L29_1.m_Talk_VTN = L30_1
L30_1 = "虽然很抱歉，但我能怎么办呢？我们当中唯一能替代重型设备搬运东西的人，就只有作为制裁者的你了。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Es tut mir leid, aber was können wir sonst tun? Von den Leuten hier sind die einzigen, die als Alternative für die schwere Ausrüstung, die wir nicht haben, fungieren können, ihr Counter."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Désolé, mais on peut pas faire autrement. Les seules qui peuvent combler notre déficit en armement lourd c'est vous, les Counters."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP9_ACT2_STAGE1_START@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 351
L30_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L31_1 = "일단 모듈이 다 조립돼야 시스템 쪽도 마무리 할 수 있으니까, 마지막까지 수고 좀 해 줘."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "とりあえすモジュールが組み立てられないとシステムも仕上げられないから、最後まで頑張って。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Since we need to finish assembling the module to complete the system, we’ll need your help until this is done."
L30_1.m_Talk_ENG = L31_1
L31_1 = "因為要先組裝好模組才能完成系統面的作業，只好麻煩你們再辛苦一下囉。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "และในเมื่อเราต้องประกอบโมดูลให้ระบบสมบูรณ์ เราก็ต้องพึ่งพวกเธอไปจนกว่าจะเสร็จเรื่องนั่นแหละ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Vì chúng tôi cần lắp ráp mô-đun để hoàn thiện hệ thống, chúng tôi sẽ cần sự trợ giúp của các cô cho đến khi xong."
L30_1.m_Talk_VTN = L31_1
L31_1 = "得先把模块全部组装好，才能让系统运行。所以大家再辛苦一下。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Sobald die Module zusammengebaut sind, kann die Systemseite fertiggestellt werden, also gebt bitte bis zum Ende euer Bestes."
L30_1.m_Talk_DEU = L31_1
L31_1 = "On doit assembler tous les modules pour rendre le système opérationnel et d'ici là, on aura besoin de votre aide."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP9_ACT2_STAGE1_START@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 351
L31_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L32_1 = "안 그래, 넘버 5?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "なあ、ナンバー5？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Isn’t that right, Number 5?"
L31_1.m_Talk_ENG = L32_1
L32_1 = "5號，你說是不是？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "จริงมั้ย หมายเลข 5?"
L31_1.m_Talk_THA = L32_1
L32_1 = "Phải không, Số 5?"
L31_1.m_Talk_VTN = L32_1
L32_1 = "对吧，5号？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Nicht wahr, Nummer 5?"
L31_1.m_Talk_DEU = L32_1
L32_1 = "N'est-ce pas, Numéro 5 ?"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
