L34_1 = "EP9_ACT2_STAGE1_START@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 351
L33_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "m_Face"
L35_1 = "UNIT_IDLE"
L33_1[L34_1] = L35_1
L34_1 = "LOOK_REPLACER_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "m_Pos"
L35_1 = "C"
L33_1[L34_1] = L35_1
L34_1 = "그렇다. 우리 중에는 육체 노동에 적합한 인원이 없으니까."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "そうだ。私たちの中では肉体労働に適合する者はいない。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "That’s right. None of us are fit for doing manual labor."
L33_1.m_Talk_ENG = L34_1
L34_1 = "是，我們當中沒有適合做苦力的人。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ก็ใช่นะสิ เราไม่เหมาะกับงานใช้แรงกันทั้งคู่นี่"
L33_1.m_Talk_THA = L34_1
L34_1 = "Đúng vậy. Không ai trong chúng tôi thích hợp để lao động chân tay cả."
L33_1.m_Talk_VTN = L34_1
L34_1 = "是的。因为我们之中，没有适合体力劳动的人员。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Stimmt. Keiner von uns ist für schwere körperliche Arbeit geeignet."
L33_1.m_Talk_DEU = L34_1
L34_1 = "C'est exact. Aucun d'entre nous n'est taillé pour le travail manuel."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP9_ACT2_STAGE1_START@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 351
L34_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "LOOK_REPLACER_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "m_Pos"
L36_1 = "C"
L34_1[L35_1] = L36_1
L35_1 = "그런데 왜 내가 넘버 5지? 다크 세븐의 새로운 멤버니까 넘버 8 아닌가?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ところでなぜ私がナンバー5なのだ？　ダークセブンの新しいメンバーなのだから、ナンバー8ではないのか？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "By the way, why am I number 5? Shouldn’t I be Number 8 since I’m the newest member of the Dark Seven?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "不過為何我是5號？我不是 Dark 7的新成員嗎？那應該是8號吧？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ว่าแต่ ทำไมฉันเป็นหมายเลข 5 นะ? ไม่ใช่ฉันต้องเป็นหมายเลข 8 เหรอ? ฉันเป็นสมาชิกคนใหม่ล่าสุดของดาร์กเซเว่นนี่"
L34_1.m_Talk_THA = L35_1
L35_1 = "Mà sao tôi lại là Số 5? Tôi phải là Số 8 vì tôi là thành viên mới nhất của Dark Seven chứ?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "但我为什么是5号？我既然是Dark Seven的新成员，不应该是8号吗？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Warum bin ich eigentlich Nummer 5? Sollte ich nicht Nummer 8 sein, da ich das neueste Mitglied der Dark Seven bin?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Au fait, pourquoi je suis Numéro 5 ? Je devrais pas plutôt être Numéro 8 puisque je viens d'arriver ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 351
L35_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L35_1.m_bWaitClick = false
L35_1.m_fWaitTime = 0
L36_1 = "LOOK_REPLACER_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "m_Pos"
L37_1 = "C_D"
L35_1[L36_1] = L37_1
L36_1 = {}
L37_1 = "EP9_ACT2_STAGE1_START@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 351
L36_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L37_1 = "후후, 그런 고정관념이야 말로 사회가 우리에게 강요한 족쇄일 뿐이지."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ふふ、そういう固定観念こそ社会が私たちに押し付けた足枷に過ぎないんだよ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Ha ha, that kind of stereotyping is merely a shackle forced upon us by society."
L36_1.m_Talk_ENG = L37_1
L37_1 = "呵呵，這只是社會硬加在我們身上的框架。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "หึหึ การเหมารวมเอาเองแบบนั้นมันเป็นตรวนที่สังคมตีล่ามเราไว้เท่านั้นแหละ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Phư phư, cái định kiến đó chỉ đơn thuần là một cái gông cùm mà xã hội buộc vào cổ chúng ta."
L36_1.m_Talk_VTN = L37_1
L37_1 = "嘿嘿。那些刻板印象只是社会强加给我们的枷锁。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Haha, solche Klischees sind nur die Fesseln, die uns die Gesellschaft auferlegt hat."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Ha ha. Tu as vraiment l'esprit étroit pour penser comme ça."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP9_ACT2_STAGE1_START@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 351
L37_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L38_1 = "명심해둬, 어둠의 정보전사 다-크 세븐의 이름은 인원수와는 관계없다고."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "よく覚えておけ、闇の情報戦士ダーークセブンの名は人数とは関係ない。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Remember, for us Daark Seven, the Info Warriors of Darkness, our name has nothing to do with our number of members."
L37_1.m_Talk_ENG = L38_1
L38_1 = "你記住，黑暗的情報戰士Dark 7，這個名字和人數完全無關！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "จำไว้นะ พวกเราคือดาร์กเซเว่น นักรบข้อมูลข่าวสารแห่งด้านมืด ชื่อของเราไม่เกี่ยวอะไรกับจำนวนสมาชิก"
L37_1.m_Talk_THA = L38_1
L38_1 = "Hãy nhớ rằng, với chúng ta, Dark Seven, các Chiến Binh Thông Tin Bóng Tối, tên chẳng liên quan gì đến số lượng thành viên cả."
L37_1.m_Talk_VTN = L38_1
L38_1 = "你要记住！我们！黑暗中的信息战士，黑暗九人帮的名字与人数无关。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Denkt daran, dass der Name der Informationskrieger der Dunkelheit, Daark Seven, rein gar nichts mit der Anzahl der Personen zu tun hat."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Le nombre de membres de Daark Seven, les informateurs de l'ombre, n'a rien à voir avec le nom de notre organisation."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP9_ACT2_STAGE1_START@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 351
L38_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L39_1 = "맞아. 가장 어감이 좋고 멋져 보이는 숫자를 이름에 붙였을 뿐이지."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "そう。一番響きがよくてカッコよさそうな数字を名前に付けただけなんだよね。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "That’s right. We just added whatever number sounded the most appropriate and cool."
L38_1.m_Talk_ENG = L39_1
L39_1 = "沒錯，單純只是覺得這個數字好唸又帥而已。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ใช่ เราแค่ใส่ๆ ตัวเลขอะไรก็ได้ที่เหมาะและเท่ที่สุดเข้าไป"
L38_1.m_Talk_THA = L39_1
L39_1 = "Đúng rồi. Chúng ta cứ thêm bất kỳ số nào nghe có vẻ phù hợp và ngầu nhất."
L38_1.m_Talk_VTN = L39_1
L39_1 = "没错。我们的名字只是将最顺耳和最酷的数字组合起来而已。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Das stimmt. Wir haben einfach die Zahl ausgewählt, die am passendsten und coolsten klang."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Il a raison. On s'est juste appelé comme ça parce que c'était classe."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP9_ACT2_STAGE1_START@39#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 39
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 351
L39_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L40_1 = "다-크 에잇이라니, 촌스러워서 참을 수 없다고."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "ダーークエイトなんて、ダサくてしょうがないんだよ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "\"Daark Eight\", such a corny name."
L39_1.m_Talk_ENG = L40_1
L40_1 = " Dark 8，聽起來不是很俗嗎？我沒辦法接受。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "\"ดาร์กเอท\" มันก็เชยไง"
L39_1.m_Talk_THA = L40_1
L40_1 = "\"Dark Eight\", một cái tên hay ho."
L39_1.m_Talk_VTN = L40_1
L40_1 = "如果变成黑暗八人帮，我完全无法接受。太土气了。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "„Daark Eight“ kann ich nicht ausstehen, weil es so kitschig klingt."
L39_1.m_Talk_DEU = L40_1
L40_1 = "On allait pas s'appeler Daark Eight, quand même ? C'est beaucoup trop cringe."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP9_ACT2_STAGE1_START@40#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 40
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 351
L40_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L41_1 = "그러니 빨리 가입할수록 더 좋은 번호를 선점할 수 있지, 너처럼."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "だから早く加入するほど、もっといい番号を先取りできる、お前のようにな。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Therefore, the earlier you join us, the better the number you get assigned to yourself, just like in your case."
L40_1.m_Talk_ENG = L41_1
L41_1 = "所以數字是先搶先贏，就像你一樣。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ดังนั้น ยิ่งมาเข้ากับเราเร็วเท่าไหร่ ก็ยิ่งได้หมายเลขดีเท่านั้น เหมือนกรณีของเธอไงล่ะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Do đó, tham gia với chúng tôi càng sớm, càng bảo đảm có số tốt cho chính mình, giống như trường hợp của cô vậy."
L40_1.m_Talk_VTN = L41_1
L41_1 = "越早加入越容易拿到好的号码，所以你很幸运。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Deshalb gilt: Je früher du bei uns einsteigst, desto besser ist die Nummer, die du zugeteilt bekommst, genau wie in deinem Fall."
L40_1.m_Talk_DEU = L41_1
L41_1 = "En tout cas, les numéros sont attribués par ordre d'arrivée. Tu es la cinquième, donc on t'appelle Numéro 5."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP9_ACT2_STAGE1_START@41#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 41
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 351
L41_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L42_1 = "이제 빈자리도 둘 밖에 안 남았어. 행운으로 생각해."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "もう空席は二つだけだ。幸運だと思え。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "We only have two more empty seats now. Consider yourself lucky."
L41_1.m_Talk_ENG = L42_1
L42_1 = "現在餘額只剩兩個，算你幸運。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ตอนนี้เรามีที่ว่างอีกแค่สองที่เท่านั้น คิดว่าตัวเองโชคดีแล้วเถอะนะ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Bây giờ chúng tôi chỉ còn hai chỗ trống nữa. Hãy vui sướng vì sự may mắn của cô đi."
L41_1.m_Talk_VTN = L42_1
L42_1 = "现在只剩下两个空位了。你应该庆幸这一点。"
L41_1.m_Talk_SCN = L42_1
