L46_1 = "그리고 다크 세븐이 아니야. 따라 해봐, 힘을 실어서! 다─크 세븐!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "あと､ダークセブンじゃない。私に続けて､力いっぱいに！　ダーークセブン!"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Also, it’s not just \"Dark Seven\". Repeat after me, with more force in your voice! DAARK SEVEN!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "而且唸的時候要注意，你跟我唸一遍，用力！Dark─7！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "แถมไม่ใช่ \"ดาร์กเซเว่น\" นะ พูดตามฉันสิ ให้เสียงหนักแน่นกว่านั้น! ดาร์กเซเว่น!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Ngoài ra, nó không chỉ là \"Dark Seven\". Lặp lại lời tôi nói, với giọng mạnh nhất có thể! DARK SEVEN!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "而且，我们不是黑暗九人帮。跟我念，要用力喊！黑——暗九人帮！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Außerdem ist es nicht „Dark Seven“. Sprich mir nach, mit aller Kraft! „Daark Seven“!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Au fait, tu ne dois pas te contenter de dire « Dark Seven » avec aussi peu d'énergie. Répète après moi : C'est « Daark Seven », en forçant sur le « a » !"
