L49_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L50_1 = "역시 우리가 눈여겨 본 멤버다워. 넘버 2랑 다르게 배우는 게 빠르다니까."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "やっぱ私たちが見込んだメンバーだね。ナンバー2とは違って飲み込みが早いんだから。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "You truly are a member that we saw potential in! Unlike Number 2, you’re a quick learner."
L49_1.m_Talk_ENG = L50_1
L50_1 = "不愧是我們看上的成員，學得很快，哪像2號。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "เธอเป็นสมาชิกที่เราเห็นศักยภาพตัวจริง! ไม่เหมือนหมายเลข 2 เธอนี่หัวไวดี"
L49_1.m_Talk_THA = L50_1
L50_1 = "Cô thực sự là một thành viên tiềm năng! Không giống như Số 2, cô học hỏi rất nhanh."
L49_1.m_Talk_VTN = L50_1
L50_1 = "不愧是我们一直关注的成员。与那个2号不同，学习速度很快嘛。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Du bist wirklich ein Mitglied, in dem wir Potenzial gesehen haben! Im Gegensatz zu Nummer 2 lernst du nämlich schnell."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Nos yeux ne nous ont pas trompé quand on t'a repérée ! Tu apprends vite toi, pas comme Numéro 2."
L49_1.m_Talk_FRA = L50_1
