L5_1[L6_1] = L7_1
L6_1 = "갑자기 우린 왜 끌어들이는 거예요?!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "なんでいきなり私たちを巻き込むんですか！？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Why are you suddenly dragging us into this?!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "幹嘛突然扯到我們身上來啦？！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ทำไมอยู่ๆ ลากเราไปเกี่ยวด้วยเนี่ย?!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tại sao cậu đột nhiên kéo chúng tôi vào chỗ này?!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "为什么突然把我们扯进去？！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Warum ziehst du uns plötzlich da mit rein?!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Euh... pourquoi vous nous mêlez à votre histoire, là ?"
L5_1.m_Talk_FRA = L6_1
