L6_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_04"
L7_1 = "AKI_FREEDOM_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "m_Pos"
L8_1 = "L"
L6_1[L7_1] = L8_1
L7_1 = "m_Crash"
L6_1[L7_1] = 30
L7_1 = "우린 그냥 델타 세븐 체험 캠프에 참가하면 지원금을 준다고 해서 온 거라고요!"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "私たちはただ、デルタセブンの体験キャンプに参加すると支援金をもらえると聞いて来ただけなんです！"
L6_1.m_Talk_JPN = L7_1
L7_1 = "We only came here because we were told that people who volunteer at the Delta Seven experience camp would receive support funding!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "我們是因為聽說參加第七三角洲部隊體驗營有錢拿才來的！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "เรามาที่นี่เพราะได้ยินว่าคนที่มาเป็นอาสาในค่าย\nเพิ่มพูนประสบการณ์เดลต้าเซเว่นจะได้ทุนสนับสนุนแค่นั้นเองนะ!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Chúng ta chỉ đến đây vì được thông báo là những người tình nguyện viên tại trại trải nghiệm Delta Seven sẽ nhận được tiền hỗ trợ!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "我们来这里是因为他们说会给我们德尔塔部队体验营的补贴！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Wir sind nur gekommen, weil uns ein Zuschuss für die Teilnahme am Delta Seven Erfahrungscamp versprochen wurde!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Nous, on est juste ici parce qu'on nous a promis une rémunération si on participait à cette activité de volontariat !"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP9_ACT2_STAGE1_START@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 351
L7_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "m_Face"
L9_1 = "UNIT_IDLE"
L7_1[L8_1] = L9_1
L8_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "m_Pos"
L9_1 = "R"
L7_1[L8_1] = L9_1
L8_1 = "마, 맞아요. 테라사이드 전역에 참가했던 사람들에겐 우대사항이 있다고 해서 온 건데……"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "そ、そうなんです。テラサイドの戦域に参加した人は優遇してくれるっていうから来たのに……"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Th-that’s right. We signed up because they said that priority will be given to people who participated in the Terraside battle..."
L7_1.m_Talk_ENG = L8_1
L8_1 = "就…就是說啊，而且還說參加過特拉賽德戰役的人會有特別優待……"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ชะ-ใช่ค่ะ เราสมัครมาเพราะเขาบอกว่าจะพิจารณาให้คนที่เข้าร่วมศึกเทอร์ราไซด์ก่อน..."
L7_1.m_Talk_THA = L8_1
L8_1 = "Đ-đúng vậy. Chúng ta đã đăng ký vì họ nói rằng những người đã tham gia trận chiến Terraside sẽ được ưu tiên..."
L7_1.m_Talk_VTN = L8_1
L8_1 = "没、没错。而且还说如果是参加过特拉赛德战役的人，还能获得额外优待……"
L7_1.m_Talk_SCN = L8_1
L8_1 = "G-genau. Wir haben uns nur angemeldet, weil uns gesagt wurde, dass Menschen, die an dem Terraside-Schlachtfeld teilgenommen haben, Priorität eingeräumt wird ..."
L7_1.m_Talk_DEU = L8_1
L8_1 = "O-Oui, c'est vrai. Et puis on nous a dit que ceux qui ont participé à l'affrontement de Terremonde étaient accueillis à bras ouverts..."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
