L9_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "m_Pos"
L10_1 = "R"
L8_1[L9_1] = L10_1
L9_1 = "이, 이런 중노동을 시킬 줄은 몰랐어요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "こ、こんな重労働をさせられるなんて知らなかったんです。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "W-we didn’t know we had to do heavy labor like this."
L8_1.m_Talk_ENG = L9_1
L9_1 = "沒…沒想到竟然叫我們做這種苦工。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ระ-เราไม่รู้นี่คะว่าต้องมาใช้แรงงานหนักแบบนี้"
L8_1.m_Talk_THA = L9_1
L9_1 = "C-chúng ta đã không biết rằng cậu lại bắt tôi lao động nặng nhọc thế này."
L8_1.m_Talk_VTN = L9_1
L9_1 = "没、没想到是这种艰苦的工作。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "W-wir wussten nicht, dass wir so schwere Arbeit leisten müssen."
L8_1.m_Talk_DEU = L9_1
L9_1 = "J-Je pensais pas qu'on serait exploitées comme ça."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EP9_ACT2_STAGE1_START@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 351
L9_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L9_1.m_bWaitClick = true
