L10_1 = "AKI_FREEDOM_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "m_Pos"
L11_1 = "L"
L9_1[L10_1] = L11_1
L10_1 = "그러고 보니 그쪽은 거기서 한 번도 본 적이 없는데 왜 은근슬쩍 여기 껴있는 거예요?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "そういえばそっちはそこで一度も見たことないのに、なにサラッとここにいるんですか？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Come to think of it, I don’t think I’ve ever seen you out there once... So why are you even here?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "不過我好像沒看過你欸？你怎麼會混進來這裡？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "จะว่าไป ฉันว่าฉันไม่เคยเจอเธอเลยนี่... แล้วทำไมเธอมาอยู่ที่นี่?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Nghĩ lại thì tôi chưa từng thấy cô ngoài đó... Vậy tại sao cô lại tới đây?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "话说，我以前从来没见过你，你为什么会和他们混在一起？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Wenn ich es mir recht überlege, glaube ich nicht, dass ich dich jemals da draußen gesehen habe ... Also, warum bist du überhaupt hier?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "D'ailleurs je ne vous ai pas vu, là-bas. Qu'est-ce que vous faites ici, au juste ?"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
