L11_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "m_Pos"
L12_1 = "R"
L10_1[L11_1] = L12_1
L11_1 = "서, 설마 저 두 아저씨들처럼 무시무시한 중범죄자 출신인 건가요?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ま、まさかあのおじさんたちのように恐ろしい重罪人なんですか？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "C-could it be that you’re a fearsome felon, just like those two guys?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "你…你該不會和那兩位大叔一樣，是可怕的重犯吧？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "จะ-จริงๆ คุณเป็นพวกอาชญากรน่ากลัวรึเปล่าคะ เหมือนสองคนนั้น?"
L10_1.m_Talk_THA = L11_1
L11_1 = "C-có phải cô là một kẻ phạm trọng tội đáng sợ, giống như hai kẻ đó không?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "难、难道你和那两个家伙一样，是可怕的重罪犯吗？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "K-könnte es sein, dass du ein furchterregender Krimineller bist, genau wie diese beiden Typen?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "V-Vous êtes pas une criminelle comme ces deux types, au moins ?"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
