L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 351
L11_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
