L11_1.m_CharStrID = L12_1
L12_1 = "m_Pos"
L13_1 = "R"
L11_1[L12_1] = L13_1
L12_1 = "그렇게 보이진 않는데…… 역시 사람은 겉모습만으론 알 수 없나 봐요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "そうは見えませんけど……やっぱり人って見た目だけでは判断できないものですね。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "You don’t look like a felon... But I guess you can’t judge a book by its cover."
L11_1.m_Talk_ENG = L12_1
L12_1 = "看起來不像啊……果然是人不可貌相呢。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "คุณดูไม่เหมือนอาชญากรเลย... แต่คนเราก็คงตัดสินกันที่ภายนอกไม่ได้"
L11_1.m_Talk_THA = L12_1
L12_1 = "Trông cô không giống một kẻ phạm tội... Nhưng tôi đoán không nên nhìn mặt mà bắt hình dong."
L11_1.m_Talk_VTN = L12_1
L12_1 = "你看起来不像耶……果然不能仅通过外表来判断一个人。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Du siehst aber nicht wie ein Krimineller aus ... Aber man darf jemanden ja nicht nur nach dem Äußeren beurteilen."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Elle n'en a pas l'air, mais... il ne faut jamais se fier aux apparences."
L11_1.m_Talk_FRA = L12_1
