L14_1.m_fBGCrashTime = 0.5
L14_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L15_1 = "그래, 우린 현대사회의 희생양일 뿐이라고!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "そうだ、私たちは現代社会の生贄なんだよ！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "That’s right! We’re merely the sacrificial lambs of modern society!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "就是說！我們只是這個社會的代罪羔羊！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ใช่! เราก็แค่ลูกแกะบูชายัญแห่งสังคมปัจจุบันหรอก!"
L14_1.m_Talk_THA = L15_1
L15_1 = "Đúng vậy! Chúng ta chỉ đơn thuần là những chú cừu non làm vật tế của xã hội hiện đại!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "是啊。我们只是现代社会的受害者！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Genau! Wir sind nur Opfer der modernen Gesellschaft!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Ouais, fais gaffe à ce que tu dis ! On est des victimes de la société nous, des boucs émissaires !"
L14_1.m_Talk_FRA = L15_1
