L17_1 = "C"
L15_1[L16_1] = L17_1
L16_1 = "……테라사이드 전역이라면 나도 그 자리에 있었는데."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "……テラサイドの戦域なら私もその場にいたが。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "...Speaking of the Terraside battle, I was there too."
L15_1.m_Talk_ENG = L16_1
L16_1 = "……若是特拉賽德戰役，那我也有在場。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "...พูดถึงเทอร์ราไซด์ ฉันก็อยู่ที่นั่นด้วยนะคะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "... Nói về trận chiến Terraside, tôi cũng đã ở đó."
L15_1.m_Talk_VTN = L16_1
L16_1 = "……如果说特拉赛德战役的话，我当时也在那里。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "... Apropos Terraside-Schlachtfeld, ich war auch dort."
L15_1.m_Talk_DEU = L16_1
L16_1 = "... Terramonde ? J'y ai assisté, moi aussi."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
