L16_1.m_CharStrID = L17_1
L17_1 = "m_Pos"
L18_1 = "C"
L16_1[L17_1] = L18_1
L17_1 = "물론 지루해서 잠들어 있긴 했지만."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "もちろん退屈で眠っていたがな。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Although I fell asleep because I got bored."
L16_1.m_Talk_ENG = L17_1
L17_1 = "只是我當時無聊到睡著。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ถึงจะหลับไปเพราะเบื่อก็เถอะค่ะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Mặc dù tôi đã ngủ gật vì cảm thấy buồn chán."
L16_1.m_Talk_VTN = L17_1
L17_1 = "不过因为太困睡着了。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Obwohl ich eingeschlafen bin, weil mir so langweilig war."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Enfin je dormais, parce que c'était d'un ennui..."
L16_1.m_Talk_FRA = L17_1
