L21_1 = "m_Crash"
L20_1[L21_1] = 10
L21_1 = "흥! 그 난리통에 잠들어 있었다니 말이 안되잖아요?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "フン！　その修羅場で寝てたなんて、あり得ないでしょう？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Hmph! How is it possible to fall asleep in all that ruckus?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "哼！打得你死我活的，怎麼可能睡得著！你唬我啊？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เฮอะ! วุ่นวายขนาดนั้นจะไปหลับได้ที่ไหน?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Hừm! Sao có thể ngủ nổi trong cái cảnh hỗn loạn đó?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "哈？在混乱的战场中睡觉？完全说不通吧？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Argh! Wie ist es möglich, in all dem Trubel einzuschlafen?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Quoi ?! Comment avez-vous pu dormir au milieu d'un chaos pareil ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP9_ACT2_STAGE1_START@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 351
L21_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "m_Face"
L23_1 = "UNIT_PRIDE"
L21_1[L22_1] = L23_1
L22_1 = "AKI_FREEDOM_NULL_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "m_Pos"
L23_1 = "L"
L21_1[L22_1] = L23_1
L22_1 = "m_Crash"
L21_1[L22_1] = 20
L22_1 = "솔직히 말해 봐요! 당신도 몰래 보상금을 노리고 온 거죠? 우리처럼!"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "正直に言ってくださいよ！　あなたも報酬金目当てでこっそり来たんじゃないですか？　私たちのように！"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Be honest! You’re only after the reward money, right? Just like we are!"
L21_1.m_Talk_ENG = L22_1
L22_1 = "你老實說！你是不是也想打賞金的主意？跟我們一樣！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "บอกมาตามตรงดีกว่า! เธอก็แค่ตามกลิ่นเงินรางวัลมาใช่มั้ย? เหมือนเราเนี่ย!"
L21_1.m_Talk_THA = L22_1
L22_1 = "Hãy trung thực đi! Anh chỉ hướng đến phần thưởng thôi phải không? Cũng giống như chúng tôi thôi!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "还是说实话吧！你也是被奖励吸引过来的吧？就像我们一样！"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Sei ehrlich! Du bist nur hinter der Belohnung her, oder? Genau wie wir!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Dites-nous la vérité ! Vous êtes juste ici pour la prime, n'est-ce pas ? Comme nous, en fait !"
L21_1.m_Talk_FRA = L22_1
