L26_1 = "FX_CUTSCEN_NOISE_RUSTLE_02"
L25_1.m_StartFXSoundName = L26_1
L26_1 = "TOMY_MASON_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "m_Pos"
L27_1 = "C"
L25_1[L26_1] = L27_1
L26_1 = "……거 참 시끄러운 녀석들이군."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "……まったく、うるさい奴らだな。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "...Man, you girls are noisy."
L25_1.m_Talk_ENG = L26_1
L26_1 = "……你們好吵！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "...ให้ตายสิ เด็กพวกนี้หนวกหูจัง"
L25_1.m_Talk_THA = L26_1
L26_1 = "... Trời ạ, các cô ồn ào quá."
L25_1.m_Talk_VTN = L26_1
L26_1 = "……你们这些家伙真的太吵了。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "... Boah, ihr Mädels seid aber laut."
L25_1.m_Talk_DEU = L26_1
L26_1 = "... Vous êtes vraiment bruyants, vous autres."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP9_ACT2_STAGE1_START@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 351
L26_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "TOMY_MASON_NULL_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "m_Pos"
L28_1 = "C"
L26_1[L27_1] = L28_1
L27_1 = "나 때는 말이야, 중장비도 없이 하루에 컨테이너를 맨손으로 열 개씩 옮겼다고."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "昔はさ、重装備もなしに素手でコンテナを一日10個も運んだんだよ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Back in my day, we used to move ten containers a day with our bare hands. And with no heavy equipment at all!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "想當年，就算沒有重型設備，我一個人一天就可以扛十個貨櫃！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "สมัยผม เราย้ายคอนเทนเนอร์สิบตู้ในวันเดียวด้วยมือเปล่า แล้วไม่มีเครื่องมือหนักแบบสมัยนี้ด้วย!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Ngày xưa, chúng tôi thường di chuyển 10 container mỗi ngày bằng tay không. Và không có trang bị nặng nào hỗ trợ cả!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "在我那个时代，每天都要徒手搬运十个集装箱，不依靠任何重型设备。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Zu meiner Zeit habe ich ohne schwere Ausrüstung zehn Container am Tag mit bloßen Händen bewegt."
L26_1.m_Talk_DEU = L27_1
L27_1 = "De mon temps on déplaçait dix conteneurs par jour, nous ! Et juste avec nos mains !"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
