L30_1 = "EP9_ACT2_STAGE1_START@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 351
L29_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "FX_CUTSCEN_NOISE_RUSTLE_02"
L29_1.m_StartFXSoundName = L30_1
L30_1 = "JERRY_MASON_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "m_Pos"
L31_1 = "L"
L29_1[L30_1] = L31_1
L30_1 = "너무 그러지 마, 어린 녀석들이 뭘 알겠어? 그저 우리가 만들어준 평화에 찌든 것뿐이잖아."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "やめろよ、子どもに何がわかるってんだ？　ただ俺たちが作ってやった平和に甘んじてるだけだろ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Don’t be too harsh on them. What do these youngsters know about hardship? They’re merely spoiled by the peace we made for them."
L29_1.m_Talk_ENG = L30_1
L30_1 = "說這些幹嘛？年輕人哪懂？他們只是享受我們努力而來的果實而已。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "อย่าร้ายกับพวกนั้นนักเลยน่า เด็กพวกนี้จะไปรู้อะไรเรื่องความลำบากล่ะ? มีแต่จะเสียคนเพราะสันติสุขที่เราสร้างไว้ให้กันทั้งนั้น"
L29_1.m_Talk_THA = L30_1
L30_1 = "Đừng quá khắt khe với họ. Những người trẻ này thì biết gì về khó khăn cơ chứ? Họ chỉ đơn thuần là bị hòa bình mà chúng ta đã tạo ra cho họ làm hư hỏng thôi."
L29_1.m_Talk_VTN = L30_1
L30_1 = "你别吓到他们，那些小家伙能懂什么？他们只会在我们缔造的和平中享受生活而已。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Sei nicht so gemein zu ihnen. Was wissen denn diese jungen Leute schon? Sie sind nur verwöhnt von dem Frieden, den wir für sie geschaffen haben."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Bah, sois pas trop dur avec eux. Les jeunes d'aujourd'hui ne réalisent pas à quel point ils sont gâtés par la paix qu'on leur a construite."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP9_ACT2_STAGE1_START@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 351
L30_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "MICKEY_MASON_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "m_Pos"
L32_1 = "R"
L30_1[L31_1] = L32_1
L31_1 = "하지만 가끔은 어른으로서 엄하게 지도해야 할 때도 있지."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "だが、たまには大人として厳しく指導しなきゃならねぇ時もある。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "However, as their elders, sometimes we have to be strict when guiding them."
L30_1.m_Talk_ENG = L31_1
L31_1 = "可是身為大人，有時候該教的還是要教吧！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "แต่ถึงยังไง ในฐานะคนที่แก่กว่า เวลาสอนกันพวกเราก็ควรเข้มงวดหน่อยสิ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tuy nhiên, vì là bề trên, đôi khi chúng ta phải nghiêm khắc để hướng dẫn họ."
L30_1.m_Talk_VTN = L31_1
L31_1 = "但有时作为长辈，也需要严格对待年轻人。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Aber manchmal müssen wir als Erwachsene auch streng sein, um sie auf den richtigen Weg zu führen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Justement, à nous de montrer l'exemple. Il faut savoir être strict, de temps à autre."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP9_ACT2_STAGE1_START@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 351
L31_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "MICKEY_MASON_NULL_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "m_Pos"
L33_1 = "R"
L31_1[L32_1] = L33_1
L32_1 = "그렇지 않으면 다시 혼란이 세상을 덮쳤을 때, 이겨나갈 힘을 기를 수 없을 테니까."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "そうじゃねえとこの世界が再び混乱に陥った時、耐えぬく力を養えねえからな。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "If we aren’t, they’ll never develop the strength to persevere when this world is plunged into chaos again."
L31_1.m_Talk_ENG = L32_1
L32_1 = "否則世界再次陷入混亂時，他們怎麼有能力能夠勝過呢！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ไม่งั้น เด็กพวกนี้จะไม่มีทางได้พัฒนาความแข็งแกร่งไว้\nมุมานะเวลาที่โลกนี้ตกอยู่ในความยุ่งเหยิงอีกครั้งได้เลย"
L31_1.m_Talk_THA = L32_1
L32_1 = "Nếu chúng ta không làm vậy, họ sẽ không bao giờ mài giũa được thế mạnh của mình để kiên trì chống trả khi thế giới này lại chìm vào hỗn loạn."
L31_1.m_Talk_VTN = L32_1
L32_1 = "否则，当混乱再次降临这个世界时，他们将没有力量克服遇到的困难。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Wenn wir es nicht sind, werden sie nie die Kraft entwickeln, durchzuhalten, wenn diese Welt wieder ins Chaos gestürzt wird."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Sinon, comment est-ce qu'il vont faire quand le monde sera de nouveau plongé dans le chaos ?"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP9_ACT2_STAGE1_START@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
