L33_1 = "TOMY_MASON_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "m_Pos"
L34_1 = "C_R_M_I"
L32_1[L33_1] = L34_1
L33_1 = "들었지, 아가씨? 그러니까 쉬지 말고 빨리빨리 움직이자고."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "聞いただろ？　お嬢ちゃん。だから休んでねえでさっさと働こうぜ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "You heard that, young lady? Therefore, stop taking breaks and let’s get this done quick."
L32_1.m_Talk_ENG = L33_1
L33_1 = "小姐，聽到沒有？少在那邊摸魚，趕快動起來！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ได้ยินแล้วใช่มั้ยสาวน้อย? เพราะงั้น หยุดอู้แล้วรีบๆ ทำให้เสร็จซะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Cô có nghe thấy không, cô gái? Hãy thôi việc trốn tránh và nhanh chóng hoàn thành công việc đi."
L32_1.m_Talk_VTN = L33_1
L33_1 = "你听到了吗，小姐？所以不要休息，还是快点干活吧。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Hast du mich gehört, Fräulein? Also hör auf dich auszuruhen und lass uns dies lieber schnell erledigen."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Tu as entendu, la miss ? Alors arrête de glander et remets-toi au travail !"
L32_1.m_Talk_FRA = L33_1
