L35_1 = "……이제 더는 못 참아!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "……もう我慢できない！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "…I can't take this anymore!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "……我真是忍無可忍！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "...ทนไม่ไหวแล้วโว้ย!"
L34_1.m_Talk_THA = L35_1
L35_1 = "... TÔI KHÔNG THỂ CHỊU NỔI NỮA!"
L34_1.m_Talk_VTN = L35_1
L35_1 = "……我！实！在！是！受！不！了！了！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "… Ich halte es nicht mehr aus!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "... Ça suffit, j'en ai marre !"
