L37_1 = "L_F_C"
L35_1[L36_1] = L37_1
L36_1 = "아저씨들이나 노동의 즐거움에 푹 빠져 계세요!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "おじさんたちは労働をたっぷり楽しんでください！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "You old geezers can take all the joys of labor by yourselves!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "要搬大叔們你們自己去搬啦！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ตาแก่พวกนี้นี่ อยากสนุกกับการใช้แรงงานก็เชิญตามสบายเลยย่ะ!"
L35_1.m_Talk_THA = L36_1
L36_1 = "Mấy người già các người cứ thoải mái mà tận hưởng lao động!"
L35_1.m_Talk_VTN = L36_1
L36_1 = "工作的乐趣还是留给大叔们继续享受吧！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ihr alten Knacker könnt euch gerne die Freuden der Arbeit teilen!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "C'est quoi, ces vieux cons ? Vous aimez tant travailler que ça ? Allez-y alors, faites-le vous même !"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
