L38_1 = "L"
L36_1[L37_1] = L38_1
L37_1 = "지원금이고 뭐고 전 관둘 거예요!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "支援金も何も、私はやめます！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "I don’t care about the support funding or whatever other rewards! I quit!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "我不幹啦！支援金什麼的我也不要啦！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "จะเงินทุนหรือรางวัลอะไรแม่ก็ไม่สนแล้วโว้ย! ไม่ทงไม่ทำแล้ว!"
L36_1.m_Talk_THA = L37_1
L37_1 = " Tôi không quan tâm đến tiền hỗ trợ hay bất kỳ phần thưởng nào khác! Tôi bỏ!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "补贴什么的我不要了！我要退出！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Auf die Kohle kann ich gerne verzichten! Ich kündige!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "J'en ai ras-le-bol, moi ! Tant pis pour la prime, je me tire !"
L36_1.m_Talk_FRA = L37_1
