L39_1 = 40
L37_1[L38_1] = L39_1
L38_1 = "애초에 돈을 벌기 위해 일을 하다니, 제 신조에도 어긋나는 일이에요!"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "大体金を稼ぐために働くなんて、私のモットーにも合わないんです！"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Working for money went against my principles in the first place anyway!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "一開始是因為有錢賺我才來的，我才不想做這種事呢！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ยังไงการทำงานแลกเงินมันก็ขัดกับหลักการนของฉันแต่แรกอยู่แล้ว!"
L37_1.m_Talk_THA = L38_1
L38_1 = "Dù sao thì làm việc vì tiền là ngược lại với nguyên tắc của tôi!"
L37_1.m_Talk_VTN = L38_1
L38_1 = "为了赚钱而工作，本身就违背我的信条！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Arbeiten für Geld geht ohnehin gegen meine Prinzipien!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Travailler pour gagner de l'argent ça a jamais été mon truc, de toute façon."
L37_1.m_Talk_FRA = L38_1
