L44_1 = "어? 어어? 쟤들 어디 가?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "え？　ええ？　あいつらどこ行くんだ？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Huh? W-what...? Where are they going?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "欸？欸欸欸？他們要去哪？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "หา? อะ-อะไรนะ...? เธอจะไปไหนน่ะ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Huh? C-cái gì...? Họ định đi đâu vậy?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "呃？嗯？他们要去哪？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Hä? Was? Wohin gehen die beiden?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Euh ? Hé ! Elles vont où comme ça ?"
