L46_1 = "L"
L44_1[L45_1] = L46_1
L45_1 = "이봐 돌아와! 목숨을 걸고 같이 싸운 전우를 버리다니 그럴 순 없어!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "おい、戻ってこい！　命をかけて一緒に戦った戦友を見捨てるなんて、あり得ねえだろうが！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Hey, come back! You can’t just abandon your comrades like that!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "喂，回來啊！怎麼可以扔下一起出生入死的戰友呢！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เฮ่ย กลับมานะ! จะมาทิ้งสหายไปดื้อๆ แบบนี้ไม่ได้นะ!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Này, quay lại! Cô không thể bỏ rơi đồng đội của mình như vậy được!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "喂，快回来！你们竟然抛弃冒着生命危险并肩作战的战友，怎么可以这样！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Hey, kommt zurück! Ihr könnt doch nicht einfach eure Kameraden im Stich lassen, die ihr Leben riskiert haben, um an eurer Seite zu kämpfen!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Revenez ! Vous pouvez pas laisser vos camarades en plan comme ça, enfin ! Et votre sens des responsabilités, alors ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP9_ACT2_STAGE1_START@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 351
L45_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "MICKEY_MASON_NULL_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "m_Pos"
L47_1 = "R"
L45_1[L46_1] = L47_1
L46_1 = "그래! 하다못해 중장비가 도착할 때까지만이라도 일해달라고!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "そうだぞ！　せめて重装備が来るまでは働いてくれよ！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "That’s right! At least work until the heavy equipment arrives!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "對啊！起碼也等到重型設備來之後再走吧！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ใช่! อย่างน้อยก็ทำงานจนกว่าอุปกรณ์หนักจะมาถึงก่อนสิ!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Đúng rồi! Ít nhất hãy làm việc cho đến khi trang bị nặng tới!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "好吧！最起码待到重型设备送到为止！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Das ist richtig! Arbeitet zumindest, bis die schwere Ausrüstung eintrifft!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Il a raison ! Restez jusqu'à l'arrivée du matériel au moins !"
L45_1.m_Talk_FRA = L46_1
