L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 351
L47_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "TOMY_MASON_NULL_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "m_Pos"
L49_1 = "C"
L47_1[L48_1] = L49_1
L48_1 = "……야, 근데 솔직히 방금 그 말은 좀 많이 쓰레기 같다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "……おい、正直今の言葉はちょっとクズすぎたぞ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "...Hey, to be honest though, that last comment you made was scummy."
L47_1.m_Talk_ENG = L48_1
L48_1 = "……喂，你說這種話還是人嗎？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "...ถึงจะตรงไปตรงมา แต่ไอ้ที่พูดอันสุดท้ายนั่นแย่มากนะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "... Này, thành thật mà nói, nhận xét cuối cùng thật là ngu ngốc mà."
L47_1.m_Talk_VTN = L48_1
L48_1 = "……嘿，说实话，你刚才说那些话的时候真像个混球。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "... Hey, um ehrlich zu sein, den letzten Kommentar hättest du dir echt sparen können."
L47_1.m_Talk_DEU = L48_1
L48_1 = "... En vrai, t'y es allé un peu fort à la fin."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP9_ACT2_STAGE1_START@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 351
L48_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "JERRY_MASON_NULL_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "m_Pos"
L50_1 = "L"
L48_1[L49_1] = L50_1
L49_1 = "맞아. 사람이 왜 그렇게 이기적이냐."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そうだ。自己中すぎんだろ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Yeah. How can you be so selfish?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "對啊，做人怎麼可以這麼自私呢？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ใช่ เห็นแก่ตัวขนาดนั้นได้ยังไงน่ะ?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Đúng òi. Sao mà có thể ích kỷ như vậy được chứ?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "没错。人怎么可以那么自私。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ja. Wie kannst du nur so egoistisch sein?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ouais. Réfléchis un peu avant de parler, ok ?"
L48_1.m_Talk_FRA = L49_1
