L4_1 = "CUTSCENE_TALK_03"
L3_1.m_StartBGMFileName = L4_1
L4_1 = "FX_CUTSCEN_NOISE_RUSTLE_02"
L3_1.m_StartFXSoundName = L4_1
L4_1 = "AKI_FREEDOM_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "m_Pos"
L5_1 = "C_R_M_I"
L3_1[L4_1] = L5_1
L4_1 = "하아……. 이럴 줄 알았으면 그냥 숙소에서 린 시엔 씨 시중이나 들고 있을 걸 그랬어요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "はあ……こうなるとわかってたなら、いっそ宿でリン・シエンさんの世話でもしてればよかったです。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Ugh... If I knew things would be like this, I would have just acted as Lin Xien’s servant at the lodging."
L3_1.m_Talk_ENG = L4_1
L4_1 = "哀……早知道我就待在宿舍伺候林·西恩還比較好！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฮึ่ม... ถ้ารู้ว่าจะเป็นอย่างนี้ ฉันคงยอมเป็นขี้ข้าหลิน ซีเอินอยู่ที่บ้านพักไปแล้ว"
L3_1.m_Talk_THA = L4_1
L4_1 = "Ugh... Nếu tôi biết mọi chuyện sẽ như thế này, tôi thà đóng vai người hầu của Lin Xien ở nhà nghỉ."
L3_1.m_Talk_VTN = L4_1
L4_1 = "啊啊啊……！早知道会这样，我还不如继续给林·西恩当跑腿呢。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Urgh ... Wenn ich das gewusst hätte, dann wäre ich einfach als Lin Xiens Dienerin in der Unterkunft geblieben."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Haa... Si j'avais su que ça se passerait comme ça, je serais restée travailler pour Lin Xien à l'auberge."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
