L7_1 = "EP9_ACT2_STAGE1_START@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 351
L6_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "m_Face"
L8_1 = "UNIT_HATE"
L6_1[L7_1] = L8_1
L7_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "m_Pos"
L8_1 = "R"
L6_1[L7_1] = L8_1
L7_1 = "하지만 무림과 관은 가까이 하면 안 된다면서 소집 통지서 보자마자 집으로 갔잖아요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "でもヤクザと警察は互いに縄張りを荒らさないものだって言いながら、招集通知書見た途端家に帰ったじゃないですか。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "But didn’t she say that she can afford a blemish on her character, but not on her clothes? Then she went right back home after receiving that draft card."
L6_1.m_Talk_ENG = L7_1
L7_1 = "正所謂井水不犯河水，所以她一看到召集通知書就回家去啦。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "แต่ซีเอินก็บอกไม่ใช่เหรอคะว่าต่างคนต่างอยู่ดีกว่า? พอได้บัตรเรียกตัวเธอเลยกลับบ้านไปเลยไง"
L6_1.m_Talk_THA = L7_1
L7_1 = "Chẳng phải nói thành phần xã hội nên tránh xa chính quyền sao. Cô ấy về nhà ngay sau khi có thông báo triệu tập."
L6_1.m_Talk_VTN = L7_1
L7_1 = "但是西恩她不是说什么“江湖人就要远离官府”，收到召集通知后就直接回家了吗。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Aber hat sie nicht gesagt, dass sie sich einen Makel an ihrem Charakter leisten kann, aber nicht an ihrer Kleidung? Dann ging sie sofort nach Hause, nachdem sie diesen Einberufungsausweis erhalten hatte."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Sauf qu'elle est rentrée chez elle dès qu'elle a vu l'annonce pour ce travail, je te rappelle ! En disant que la pègre ne fait pas dans le caritatif..."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP9_ACT2_STAGE1_START@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 351
L7_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "AKI_FREEDOM_NULL_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "m_Pos"
L9_1 = "L"
L7_1[L8_1] = L9_1
L8_1 = "……역시 세상에 우리 편은 아무도 없어요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "……やっぱりこの世界に私たちの味方は誰もいないんです。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "There really is nobody on our side..."
L7_1.m_Talk_ENG = L8_1
L8_1 = "……這個世界果然沒有人站在我們這一邊。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ไม่มีใครเข้าข้างเราเลยจริงๆ..."
L7_1.m_Talk_THA = L8_1
L8_1 = "Thực sự không có ai đứng về phía chúng ta cả..."
L7_1.m_Talk_VTN = L8_1
L8_1 = "……果然世界上没有人站在我们这边。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Es ist wirklich niemand auf unserer Seite ..."
L7_1.m_Talk_DEU = L8_1
L8_1 = "On peut vraiment compter sur personne..."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EP9_ACT2_STAGE1_START@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 351
L8_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "m_Face"
L10_1 = "UNIT_SERIOUS"
L8_1[L9_1] = L10_1
L9_1 = "AKI_FREEDOM_NULL_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "m_Pos"
L10_1 = "L"
L8_1[L9_1] = L10_1
L9_1 = "m_Crash"
L8_1[L9_1] = 30
L9_1 = "이젠 에이미도 없으니까 민서양도 맘을 굳게 먹어야 해요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "もうエイミーもいないんですから、クロボシさんもしっかりしないとダメです。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Now that even Amy is no longer with us, you must also steel yourself, Minseo."
L8_1.m_Talk_ENG = L9_1
L9_1 = "現在艾米又不在，你千萬不能動搖。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ในเมื่อตอนนี้แม้แต่เอมี่ก็ไม่ได้อยู่กับเราแล้ว เธอก็ต้องเข้มแข็งไว้นะมินซอ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Bây giờ ngay cả Amy không còn ở bên chúng ta nữa, cậu cũng phải tự rèn luyện bản thân đi, Minseo."
L8_1.m_Talk_VTN = L9_1
L9_1 = "既然现在艾米不在了，亚子小姐也必须坚强起来。"
L8_1.m_Talk_SCN = L9_1
