L11_1 = "그러고 보니 여기 올 때는 헬리콥터를 타고 왔던 것 같은데?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "そういえばここに来る時にはヘリだったような？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Now that you mention it, didn’t we come here on helicopters...?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "這麼說來，我們來的時候是搭直升機來的吧？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "จะว่าไป เรานั่งเฮลิคอปเตอร์มาที่นี่กันไม่ใช่เหรอ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Không phải chúng ta đến đây bằng máy bay trực thăng sao...?"
