L12_1 = "서, 설마 그 길을 전부 걸어가겠다는 건 아니죠?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ま、まさかその道程を全部歩いて行こうってわけじゃないですよね？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "S-surely you don’t intend on walking all the way back?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "我…我們該不會都要用走的吧？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ชะ-ใช่นะสิ คุณคงไม่ได้คิดจะเดินกลับใช่มั้ยคะ?"
L11_1.m_Talk_THA = L12_1
