L12_1[L13_1] = L14_1
L13_1 = "제가 그렇게 성실할 리가 없잖아요! 부, 분명 여기 어딘가에 대중교통이 있을 거예요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "私がそんなに真面目なわけないでしょう！　き、きっとこのあたりに公共交通機関があるはずです。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "There’s no way that I would be that hardcore! Th-there must be public transportation somewhere around here."
L12_1.m_Talk_ENG = L13_1
L13_1 = "我怎麼可能這麼呆！這…這附近一定有大眾交通工具的啦！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ฉันไม่บ้าขนาดนั้นหรอก! ถะ-แถวนี้ต้องมีขนส่งมวลชนอยู่สักที่แหละ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Tôi không điên vậy! C-chắc phải có phương tiện giao thông công cộng nào đó quanh đây."
L12_1.m_Talk_VTN = L13_1
L13_1 = "我也不能这么蠢吧！这、这附近一定有公共交通工具。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Auf keinen Fall! Es muss hier doch irgendwo öffentliche Verkehrsmittel geben."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Ça va pas la tête ?! Il doit bien avoir un bus quelque part, non... ?"
L12_1.m_Talk_FRA = L13_1
