L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "ほ、本当ですね？　バスが来てます！　廣瀬さん、すごいです！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Oh, there is! A bus is coming! You’re amazing, Ms. Hirose!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "真…真的欸！是巴士！你好厲害喔！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "โอ๊ะจริงด้วย! รถเมล์มาแล้ว! คุณนี่สุดยอดไปเลยค่ะคุณฮิโรเสะ!"
L16_1.m_Talk_THA = L17_1
