L26_1 = "CUTSCENE_TALK_02"
L25_1.m_StartBGMFileName = L26_1
L26_1 = "INSPECTOR_NPC_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "m_Pos"
L27_1 = "C"
L25_1[L26_1] = L27_1
L26_1 = "이봐 너희들. 저쪽 기지 방향에서 오는 것 같은데, 델타 세븐 부대와 무슨 관계지?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "おい、君たち。あそこの基地から来てるようだが、デルタセブンとはなんの関係だ？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "You two. You seem to be coming from the base. What is your relationship with Delta Seven?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "喂，你們兩個！我看你們好像是從基地的方向過來的，你們和第七三角洲部隊是什麼關係？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "สองคนนั้นน่ะ ท่าทางเหมือนออกมาจากฐานนี่ เกี่ยวข้องอะไรกับเดลต้าเซเว่นหา?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Có vẻ như hai người đến từ căn cứ. Các cô với Delta Seven có quan hệ gì?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "喂，你们。看起来是从那边的基地方向过来的。你们和德尔塔部队有什么关系？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Hey, ihr zwei! Ihr scheint von der Basis zu kommen. In welcher Beziehung steht ihr zu Delta Seven?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Hé, vous deux. Vous venez de la base là-bas, non ? Quelle est votre relation avec Delta Seven ?"
L25_1.m_Talk_FRA = L26_1
