L29_1 = "m_Face"
L30_1 = "UNIT_SURPRISE"
L28_1[L29_1] = L30_1
L29_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "m_Pos"
L30_1 = "R"
L28_1[L29_1] = L30_1
L29_1 = "m_Crash"
L28_1[L29_1] = 30
L29_1 = "히, 히로세 씨! 분위기가 심상치 않아요!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ひ、廣瀬さん！　雰囲気がおかしいです！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "M-Ms. Hirose! Something doesn’t feel right!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "廣…廣瀨！好像不太對勁欸！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ฮะ-ฮิโรเสะคะ! ดูจะไม่เข้าท่าแล้วค่ะ!"
L28_1.m_Talk_THA = L29_1
L29_1 = "H-Hirose! Có gì đó không ổn!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "广、广濑！气氛有些不对劲！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "A-Aki! Irgendwas stimmt hier nicht!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "A-Aki ! Je le sens pas, là..."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP9_ACT2_STAGE1_START@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 351
L29_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "AKI_FREEDOM_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "m_Pos"
L31_1 = "L"
L29_1[L30_1] = L31_1
L30_1 = "거, 걱정 말아요! 이래봬도 예전에 에이미에게 히치하이킹 하는 법을 배웠다고요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "し、心配しないでください！　こう見えても昔エイミーにヒッチハイクのやり方を教わったんです。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "D-don’t worry! I learned how to hitchhike from Amy before!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "別…別擔心！之前不是有和艾米學過怎麼搭便車嗎！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "มะ-ไม่ต้องห่วงนะ! ฉันเรียนรู้วิธีโบกรถจากเอมี่มาแล้ว!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Đ-đừng lo! Tôi đã học cách đi nhờ xe từ Amy rồi!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "别、别担心！我以前从艾米那里学过如何搭便车。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "M-mach dir keine Sorgen! Ich habe früher von Amy gelernt, wie man per Anhalter fährt!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "N-Ne t'inquiète pas ! Amy m'a appris les rudiments de l'autostop, je vais gérer !"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP9_ACT2_STAGE1_START@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 351
L30_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "m_Face"
L32_1 = "UNIT_IDLE"
L30_1[L31_1] = L32_1
L31_1 = "AKI_FREEDOM_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "m_Pos"
L32_1 = "L"
L30_1[L31_1] = L32_1
L31_1 = "적당히 분위기 맞춰서 칭찬 몇 마디만 해 주면 분명 공짜로 태워줄 거예요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "適当に合わせてちょっと誉めてあげれば、きっとただで乗せてくるはずです。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "If we just go with the flow and drop a few compliments, they’ll definitely give us a free ride."
L30_1.m_Talk_ENG = L31_1
L31_1 = "先看一下氣氛，然後再稱讚幾句，對方應該就會讓我們搭便車吧！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ถ้าเราตามน้ำไปแล้วหยอดคำหวานซะหน่อย พวกเขาก็จะให้เราขึ้นรถฟรีไปเองแหละ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Nếu chúng ta cứ thuận theo và khen vài lời, họ chắc chắn sẽ cho chúng ta đi nhờ miễn phí."
L30_1.m_Talk_VTN = L31_1
L31_1 = "只要应景地赞美几句，一定会免费送我们一程。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wenn wir für die richtige Stimmung sorgen und ein paar Komplimente machen, werden wir auf jeden Fall kostenlos mitgenommen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Si on va dans leur sens et qu'on leur fait quelques compliments, je suis sûre que ces types voudront bien nous prendre avec eux."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
