L34_1 = 2
L35_1 = 0.15
L33_1[1] = L34_1
L33_1[2] = L35_1
L31_1[L32_1] = L33_1
L32_1 = "어쩌면 불쌍해 보여서 밥도 사줄지 몰라요!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "もしかしたら可哀想だと思ってご飯をおごってくれるかもしれませんよ！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "They might even take pity on us and buy us a meal!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "說不定我們再裝一下可憐，對方還會請我們吃飯呢！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "หรืออาจถึงขั้นสงสารจนซื้อข้าวให้กินเลยนะ!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Họ thậm chí có thể thương hại chúng ta và mua đồ ăn cho chúng ta nữa!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "说不定看我们可怜，还会请我们吃顿饭呢！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Vielleicht haben sie sogar Mitleid mit uns und spendieren uns eine Mahlzeit!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Peut-être même qu'ils auront pitié de nous et qu'ils nous payeront un repas !"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP9_ACT2_STAGE1_START@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 351
L32_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L32_1.m_bWaitClick = true
