L34_1 = "R"
L32_1[L33_1] = L34_1
L33_1 = "m_Crash"
L32_1[L33_1] = 15
L33_1 = "히로세 씨랑 같이 다닌다는 사실이…… 제게도 가끔 민망할 때가 있어요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "廣瀬さんと一緒だということが……たまに恥ずかしくなる時があります。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Sometimes... I feel embarrassed being around with you, Ms. Hirose..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "和你一起行動……老實說我偶爾也有點不安。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "บางที... ฉันก็อายจังค่ะที่ต้องอยู่กับคุณ คุณฮิโรเสะ..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Đôi khi... tôi cảm thấy xấu hổ khi ở bên cậu đấy, cô Hirose..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "为什么我有的时候会觉得……和广濑一起行动很丢脸……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Manchmal ... ist es mir peinlich, mit dir unterwegs zu sein, Aki ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "... Parfois j'ai un peu hontre de traîner avec toi, Amy."
L32_1.m_Talk_FRA = L33_1
