L36_1 = "UNIT_SERIOUS"
L34_1[L35_1] = L36_1
L34_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_04"
L35_1 = "AKI_FREEDOM_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "m_Pos"
L36_1 = "C_L_M_I"
L34_1[L35_1] = L36_1
L35_1 = "저, 저희는 델타 세븐 부대와 아무 관련이 없어요!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "わ、私たちはデルタセブンとはなんの関係もありません！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "W-we aren’t connected to Delta Seven in any way!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "我…我們和第七三角洲部隊完全沒關係！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ระ-เราไม่เกี่ยวอะไรกับเดลต้าเซเว่นนะ!"
L34_1.m_Talk_THA = L35_1
L35_1 = "C-chúng tôi chẳng có quan hệ gì với Delta Seven cả!"
L34_1.m_Talk_VTN = L35_1
L35_1 = "我、我们和德尔塔部队没有任何关系！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "W-wir haben nichts mit der Delta Seven zu tun!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Delta Seven ? N-Nous n'avons rien à voir avec cette organisation !"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP9_ACT2_STAGE1_START@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 351
L35_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L35_1.m_bWaitClick = true
