L37_1 = "C"
L35_1[L36_1] = L37_1
L36_1 = "m_Crash"
L35_1[L36_1] = 15
L36_1 = "그냥 체험 캠프에 온 민간인 비슷한 거라고요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "ただ体験キャンプに来た一般人のようなものです。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "We’re just civilians who participated in their experience camp."
L35_1.m_Talk_ENG = L36_1
L36_1 = "我們是來參加體驗營的普通人！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เราเป็นแค่พลเมืองที่มาร่วมค่ายเพิ่มพูนประสบการณ์ของพวกนั้นเท่านั้น"
L35_1.m_Talk_THA = L36_1
L36_1 = "Chúng tôi chỉ là những thường dân tham gia trại trải nghiệm của họ thôi."
L35_1.m_Talk_VTN = L36_1
L36_1 = "我们只是来到体验营的平民。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Wir sind nur Zivilisten, die an Delta Sevens Erfahrungscamp teilgenommen haben."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Nous ne sommes que de simples civiles venues participer à une activité de volontariat."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP9_ACT2_STAGE1_START@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 351
L36_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "m_Face"
L38_1 = "UNIT_PRIDE"
L36_1[L37_1] = L38_1
L37_1 = "AKI_FREEDOM_NULL_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "m_Pos"
L38_1 = "C"
L36_1[L37_1] = L38_1
L37_1 = "그러니까…… 저기 가까운 도시에 지하철 있는 곳 까지만 태워 주시면 안될까요?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "だから……近い街の地下鉄の駅まで乗せてもらえませんか？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "So... Can you just drop us off at the subway station in the nearest city?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "可以……載我們到鄰近城市有地鐵的地方嗎？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "งั้น... ช่วยพาเราไปส่งที่สถานีรถไฟใต้ดินในเมืองที่ใกล้ที่สุดหน่อยได้มั้ย?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Vậy... Các anh có thể đưa chúng tôi xuống ga tàu điện ngầm ở thành phố gần nhất được không?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "所、所以……你们能开车送我们到最近有地铁的城市吗？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Also ... Können Sie uns einfach an der U-Bahn-Station in der nächsten Stadt absetzen?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Alors, euh... vous voulez bien nous déposer à une station de métro dans la ville la plus proche ?"
L36_1.m_Talk_FRA = L37_1
