L43_1 = "EP9_ACT2_STAGE1_START@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 351
L42_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L42_1.m_bWaitClick = true
