L43_1 = "INSPECTOR_NPC_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "m_Pos"
L44_1 = "C"
L42_1[L43_1] = L44_1
L43_1 = "여기는 선발대. 델타 세븐과…… 아무튼 관계 있어 보이는 인원들과 조우했다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "こちら先発隊。デルタセブンと……とにかく関わりのありそうな者たちと遭遇した。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "This is Spearhead. We have encountered... individuals who seem to be connected with Delta Seven."
L42_1.m_Talk_ENG = L43_1
L43_1 = "這裡是先遣隊，發現應該和第七三角洲部隊……有關係的人士。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "นี่สเปียร์เฮด... เราพบบุคคลที่เหมือนจะมีความเกี่ยวข้องกับเดลต้าเซเว่น"
L42_1.m_Talk_THA = L43_1
L43_1 = "Đây là Spearhead. Chúng tôi đã gặp... những người dường như có liên hệ với Delta Seven."
L42_1.m_Talk_VTN = L43_1
L43_1 = "这里是先遣队。遇到看起来……和德尔塔部队有关系的人。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Hier spricht Aufklärer. Wir sind Personen begegnet, die mit Delta Seven in Verbindung zu stehen scheinen."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Ici l'équipe de reconnaissance. Nous venons de tomber sur... deux individus suspects qui semblent en lien avec Delta Seven."
L42_1.m_Talk_FRA = L43_1
