L46_1[L47_1] = L48_1
L47_1 = "m_Crash"
L48_1 = 40
L46_1[L47_1] = L48_1
L47_1 = "전원 전투 준비! 저항하면 사살해도 상관없다."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "全員戦闘準備！　抵抗する場合、射殺しても構わない。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "All hands prepare for battle! Kill them if they resist."
L46_1.m_Talk_ENG = L47_1
L47_1 = "全員準備戰鬥！反抗者死。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ทุกคนพร้อมรบ! ถ้าขัดขืนก็ฆ่าได้เลย"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tất cả hãy chuẩn bị chiến đấu! Cứ giết nếu chúng kháng cự."
L46_1.m_Talk_VTN = L47_1
L47_1 = "全员准备战斗！反抗的话，就地格杀。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Alle bereitmachen für den Kampf! Tötet sie, falls sie sich widersetzen sollten."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Tout le monde, préparez-vous à combattre ! Tuez ces deux-là si elles résistent."
L46_1.m_Talk_FRA = L47_1
