L50_1 = "m_Face"
L51_1 = "UNIT_SURPRISE"
L49_1[L50_1] = L51_1
L50_1 = "AKI_FREEDOM_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "m_Pos"
L51_1 = "L"
L49_1[L50_1] = L51_1
L50_1 = "어, 어째서? 차를 태워달라고 했더니 다짜고짜 총을 겨누는 거죠?!"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ど、どうして？　車に乗せてって言ったのにいきなり銃を構えるんですか！？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "W-what should we do? I asked for a ride and they’re suddenly pointing guns at us!!"
L49_1.m_Talk_ENG = L50_1
L50_1 = "為…為什麼？不過就是想搭個便車，幹嘛拿槍指著我們？！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ทะ-ทำไงกันดีล่ะเรา? ฉันขอขึ้นรถฟรีแล้วอยู่ๆ พวกเขาก็ชี้ปืนใส่เฉยเลย!!"
L49_1.m_Talk_THA = L50_1
L50_1 = "C-chúng ta nên làm gì đây? Tôi xin đi nhờ xe và họ đột nhiên chĩa súng vào chúng ta!!"
L49_1.m_Talk_VTN = L50_1
L50_1 = "呃，为什么？我们只是要搭个便车，他们为什么要用枪指着我们？！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "W-was sollen wir tun? Ich habe um eine Mitfahrgelegenheit gebeten und sie richten plötzlich ihre Waffen auf uns!"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Q-Quoi ? J'ai juste demandé un coup de main moi, pourquoi est-ce que vous nous braquez comme ça ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP9_ACT2_STAGE1_START@150#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 351
L50_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "m_Pos"
L52_1 = "R"
L50_1[L51_1] = L52_1
L51_1 = "아직도 모르시나요 히로세 씨? 우리에게 세상은 그냥 난이도 조절에 실패한 망겜이라고요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "まだわからないんですか、廣瀬さん？　私たちにとってこの世界は、ただ難易度調整に失敗したクソゲーなんですよ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Don’t you get it Ms. Hirose? The world has come to get us, and it's game over!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "廣瀨，你還搞不清楚狀況嗎？世界對我們而言就像是難度調整失敗的糞Game。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ไม่เข้าใจอีกเหรอคะคุณฮิโรเสะ? ชีวิตสู้กลับแล้วค่ะ และเราก็เกมโอเวอร์แล้ว!"
L50_1.m_Talk_THA = L51_1
L51_1 = "Không hiểu sao, tiểu thư Hirose? Thế giới đã đến để bắt chúng ta, và kết thúc rồi!!!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "你还不明白吗，广濑？对我们来说，这个世界是一个无法控制难度的失败游戏！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Verstehst du es denn nicht, Aki? Für uns ist die Welt nur ein chaotisches Spiel, bei dem die Schwierigkeitsstufe nicht angepasst werden konnte."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Tu n'as toujours pas compris, Aki ? Depuis le début, on joue en hard mode dans un monde où on peut pas régler la difficulté !"
L50_1.m_Talk_FRA = L51_1
