L12_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L13_1 = "저건…… 군인들 같은데? 훈련 중인가?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "あれは……軍人だな？　訓練中なのか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Those are... soldiers? Is this a military drill?"
L12_1.m_Talk_ENG = L13_1
