L13_1[L14_1] = L15_1
L14_1 = "LOOK_REPLACER_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "m_Pos"
L15_1 = "C"
L13_1[L14_1] = L15_1
L14_1 = "아니. 가능성 트리 평가 분석에 따르면 진짜 공격일 확률 95% 이상이다."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "いいや。可能性ツリー評価の分析によると、本当の攻撃である確率は95％以上だ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "No. Based on the possibility tree evaluation analysis, the probability of this being an actual attack is over 95%."
L13_1.m_Talk_ENG = L14_1
L14_1 = "不對，根據可能性樹的分析結果，有95%以上的機率是真的攻擊。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ไม่นะคะ จากการวิเคราะห์เพื่อประเมินความเป็นไปได้ในแบบต่างๆ โอกาสที่นี่จะเป็นการโจมตีจริงๆ มีมากกว่า 95% ค่ะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Không. Dựa trên phân tích đánh giá cây xác suất, khả năng đây là một cuộc tấn công thực sự là hơn 95%."
L13_1.m_Talk_VTN = L14_1
L14_1 = "不。 根据概率树评估分析，是真正攻击的概率在95%以上。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Nein. Laut der Analyse des Wahrscheinlichkeitsbaums liegt die Wahrscheinlichkeit, dass es sich um einen echten Angriff handelt, bei über 95 %."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Non. D'après mon analyse, la probabilité qu'il s'agisse d'une attaque réelle est supérieure à 95%."
L13_1.m_Talk_FRA = L14_1
