L16_1 = "EP9_ACT2_STAGE1_START@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 351
L15_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L16_1 = "하하, 넘버 5가 아직 경험이 부족한가 본데 실전이라는 건 그리 쉽게 벌어지는 일이 아냐."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "はは、ナンバー5はまだ経験が足りないみたいだけど、実戦っていうのはそう簡単に始まらないんだよ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Haha, maybe it’s your lack of experience, Number 5, but actual combat doesn’t break out so easily."
L15_1.m_Talk_ENG = L16_1
L16_1 = "哈哈，年輕人終究是年輕人，哪有那麼容易就開戰的？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ฮ่าฮ่า อาจเพราะเธอยังอ่อนประสบการณ์นะ หมายเลข 5 แต่การต่อสู้จริงๆ ไม่เกิดขึ้นง่ายๆ หรอก"
L15_1.m_Talk_THA = L16_1
L16_1 = "Haha, có thể đó là do cô thiếu kinh nghiệm, Số 5 ạ, thực tế chiến đấu không nổ ra dễ dàng như vậy đâu."
L15_1.m_Talk_VTN = L16_1
L16_1 = "哈哈，我觉得5号还是缺乏经验。毕竟实战情况并不是那么容易发生。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Haha, vielleicht liegt es an deiner mangelnden Erfahrung, Nummer 5, aber der eigentliche Kampf bricht nicht so leicht aus."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Ha ha. On voit que tu manques encore d'expérience, Numéro 5. Les combats réels n'éclatent pas sans raison comme ça."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "EP9_ACT2_STAGE1_START@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 351
L16_1.m_CutScenStrID = "EP9_ACT2_STAGE1_START"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L17_1 = "기억해두라고, 단순한 가능성 확률 계산만으로는 현실을 정확히 분석할 수 없지."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "覚えておくといい、単なる可能性の確率計算だけでは現実は正確に分析できないってこと。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Remember this: reality cannot be accurately analyzed purely with simple probability calculations."
L16_1.m_Talk_ENG = L17_1
L17_1 = "你記住，單憑計算可能性機率，是無法準備分析現實的。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "จำไว้นะ จะเอาแค่การคำนวณความน่าจะเป็นง่ายๆ มาวิเคราะห์ความเป็นจริงให้ออกมาเป๊ะๆ น่ะไม่ได้หรอก"
L16_1.m_Talk_THA = L17_1
L17_1 = "Hãy nhớ điều này: thực tế không thể được phân tích chính xác hoàn toàn bằng các phép tính xác suất đơn giản."
L16_1.m_Talk_VTN = L17_1
L17_1 = "记住了，仅靠简单的概率计算是无法准确分析现实的。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Denk daran: Die Realität kann nicht mit einfachen Wahrscheinlichkeitsrechnungen genau analysiert werden."
L16_1.m_Talk_DEU = L17_1
L17_1 = "N'oublie pas ceci : la réalité ne pourra jamais être analysée simplement par le biais de calculs de probabilités."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
