L18_1 = "LOOK_REPLACER_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "m_Pos"
L19_1 = "C"
L17_1[L18_1] = L19_1
L18_1 = "과연, 덕분에 새로운 항목을 학습했다."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "なるほど、おかげで新しい項目を学習した。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Oh... Thanks to you, I’ve acquired new knowledge."
L17_1.m_Talk_ENG = L18_1
L18_1 = "原來如此，謝謝你讓我有新的學習。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "โอ้โห... ขอบคุณนะคะ ฉันได้ความรู้ใหม่อีกแล้วค่ะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Wow... Nhờ anh, tôi đã biết thêm kiến thức mới."
L17_1.m_Talk_VTN = L18_1
L18_1 = "确实，多亏了你，我学到了新的知识。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Oh ... Dank dir habe ich etwas Neues dazugelernt."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Oh, je vois. Merci pour ces nouvelles données."
L17_1.m_Talk_FRA = L18_1
