L19_1 = "LOOK_REPLACER_NULL_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "m_Pos"
L20_1 = "C"
L18_1[L19_1] = L20_1
L19_1 = "정확히 우리가 있는 방향으로 미사일이 날아오고 있는데 공격이 아닐 수 있다니."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "正確に私たちのいる方向へミサイルが飛んできているというのに攻撃でない可能性があるなんてな。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Despite a missile flying directly towards our exact location, this may not be an attack..."
L18_1.m_Talk_ENG = L19_1
L19_1 = "導彈就這樣筆直地朝我們飛過來，結果竟然不是真的攻擊。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ถึงจะมีมิสไซล์กำลังพุ่งตรงมาทางนี้ นี่ก็อาจไม่ใช่การโจมตี..."
L18_1.m_Talk_THA = L19_1
L19_1 = "Mặc dù có một chiếc tên lửa đang bay thẳng đến đúng chỗ này, nhưng đây có thể không phải là một cuộc tấn công..."
L18_1.m_Talk_VTN = L19_1
L19_1 = "即使导弹正朝着我们所在的方向飞过来，也不一定会是攻击的前兆。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Die Raketen fliegen zwar genau in unsere Richtung, aber es könnte ja auch kein Angriff sein."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Donc, malgré ce missile qui vole droit sur nous, nous ne sommes pas en train de subir une attaque ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
