L21_1 = "C"
L19_1[L20_1] = L21_1
L20_1 = "현실이란 정말 놀라운 가능성의 집합체인 듯 하다."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "現実というものは本当に驚くべき可能性の集合体のようだ。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Reality truly is an amazing agglomeration of possibilities."
L19_1.m_Talk_ENG = L20_1
L20_1 = "所謂的現實，彷彿是驚人可能性的集合體。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ความเป็นจริงนี่เป็นการรวมตัวกันอย่างน่าอัศจรรย์ของสารพัดความน่าจะเป็นจริงๆ ค่ะ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Thực tế có vẻ là sự tập hợp đáng kinh ngạc của các khả năng."
L19_1.m_Talk_VTN = L20_1
L20_1 = "现实的确是一个惊人的可能性集合。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Die Realität scheint eine Ansammlung wirklich erstaunlicher Möglichkeiten zu sein."
L19_1.m_Talk_DEU = L20_1
L20_1 = "La réalité est vraiment une convergence incroyable de possibilités."
L19_1.m_Talk_FRA = L20_1
