L21_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_04"
L21_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L22_1 = "미사일이 날아온다니! 그런 건 빨리빨리 말해야지!"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "ミサイルが飛んできてる！？　そういうことは早く言ってよ！"
L21_1.m_Talk_JPN = L22_1
L22_1 = "There’s a missile flying in our direction?! You should’ve mentioned this earlier!!"
L21_1.m_Talk_ENG = L22_1
L22_1 = "導彈飛過來？！這麼重要的事你怎麼不早說！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "มีมิสไซล์มาทางนี้เรอะ?! ก็น่าจะบอกเราเรื่องนั้นก่อนเซ่!!"
L21_1.m_Talk_THA = L22_1
L22_1 = "Có một chiếc tên lửa đang bay về hướng của chúng ta ư?! Đáng lẽ cô phải nói sớm hơn chứ!!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "导弹飞过来了！你怎么不早说！"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Es fliegt eine Rakete in unsere Richtung?! Das hättest du auch mal etwas früher erwähnen können!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Un missile ?! Mais tu pouvais pas le dire plutôt, non ?"
L21_1.m_Talk_FRA = L22_1
