L24_1 = "C"
L22_1[L23_1] = L24_1
L23_1 = "호오, 빨리 말했다면 다른 가능성이 발생하는 건가?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ほう、早く言えば違う可能性が発生するのか？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Oh? If I told you this earlier, then would it have created another probability?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "喔？若是我早點說的話，會有不同的可能性嗎？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "อ้าว? ถ้าฉันบอกก่อน มันจะสร้างความน่าจะเป็นอีกชุดขึ้นมาเหรอคะ?"
L22_1.m_Talk_THA = L23_1
L23_1 = "Ồ? Nếu tôi nói với cậu điều này sớm hơn, liệu nó có tạo ra một xác suất khác không?"
L22_1.m_Talk_VTN = L23_1
L23_1 = "哦哦，如果我早点说，会出现另一种可能性吗？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Oh? Wenn ich dir das früher gesagt hätte, hätte es dann eine andere Wahrscheinlichkeit ergeben?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Oh ? Si je vous l'avais dit plutôt, cela aurait-il créé de nouvelles possibilités ?"
L22_1.m_Talk_FRA = L23_1
