L24_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L25_1 = "맞아! 저 멍청이 때문에 우리가 여기서 다 죽을 가능성이 조금 줄어들었겠지!"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "そう！　あのバカのせいで私たちがここで皆殺しになる可能性がちょとは減っただろう！"
L24_1.m_Talk_JPN = L25_1
L25_1 = "That’s right! It would’ve slightly decreased our chances of dying here because of his stupidity!"
L24_1.m_Talk_ENG = L25_1
L25_1 = "沒錯！那我們全都死在這裡的可能性會減低一點！"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เออสิ! มันจะลดโอกาสที่เราจะตายเพราะความโง่ของเธอไปได้หน่อยไง!"
L24_1.m_Talk_THA = L25_1
L25_1 = "Có chứ! Nó sẽ làm giảm một chút nguy cơ toi mạng của chúng ta ở đây, vì sự ngu ngốc của cô!"
L24_1.m_Talk_VTN = L25_1
L25_1 = "没错！如果你这个白痴早说，我们都死在这里的可能性可能就会减少一点！"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Oh ja! Es hätte unsere Chancen, wegen seiner Dummheit hier zu sterben, minimal verringert!"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Évidemment ! Ça aurait légèrement diminué nos chances de mourir ici à cause de ces deux imbéciles !"
L24_1.m_Talk_FRA = L25_1
